(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0024.js"] = [{"id":"poem-9e648fe021035dfa443002b2","title":"春江花月夜","author":"张若虚","dynasty":"唐","verses":["春江潮水连海平，海上明月共潮生。","滟滟随波千万里，何处春江无月明？","江流宛转遶芳甸，月照花林皆似霰。","空里流霜不觉飞，汀上白沙看不见。","江天一色无纤尘，皎皎空中孤月轮。","江畔何人初见月，江月何年初照人？","人生代代无穷已，江月年年秖相似。","不知江月待何人？但见长江送流水。","白云一片去悠悠，青枫浦上不胜愁。","谁家今夜扁舟子，何处相思明月楼？","可怜楼上月裴回，应照离人妆镜台。","玉户帘中卷不去，捣衣砧上拂还来。","此时相望不相闻，愿逐月华流照君。","鸿雁长飞光不度，鱼龙潜跃水成文。","昨夜闲潭梦落花，可怜春半不还家。","江水流春去欲尽，江潭落月复西斜。","斜月沈沈藏海雾，碣石潇湘无限路。","不知乘月几人归，落月摇情满江树。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-587422bf-52ac-4755-97fc-1b22ad6ae626","tags":["长江","思念","清商曲辞","月亮","春天","乐府","花","写花"]},{"id":"poem-9e66a8f7b753204346b5116e","title":"送人游塞","author":"卿云","dynasty":"唐","verses":["去去玉关路，省君曾未行。","塞深多伏寇，时静亦屯兵。","雪每先秋降，花尝近夏生。","闲陪射雕将，应到受降城。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-ca192c09-7183-4004-a9e7-a2c8a91637ac","tags":[]},{"id":"poem-9e66b3fff387f27fa508794e","title":"浣溪沙·漠漠轻寒上小楼","author":"秦观","dynasty":"宋","verses":["漠漠轻寒上小楼。","晓阴无赖似穷秋。","淡烟流水画屏幽。","自在飞花轻似梦，无边丝雨细如愁。","宝帘闲挂小银钩。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-68","tags":["宋词三百首"]},{"id":"poem-9e6b2d9721b19043b72ac526","title":"和吕御史咏院中藂竹","author":"张纮","dynasty":"唐","verses":["闻君庭竹咏，幽意岁寒多。","叹息为冠小，良工将奈何。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-03bbaefb-d7af-4660-a669-842569a46c2d","tags":[]},{"id":"poem-9e6d4d49aa62a145cac1d882","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["猛思那日临行际，蒙岳丈惜伊玉树，兼爱我寒枝。","念行囊空虚，欣然便周全助路资。","召共居，感此义山恩海深难弃。","细踌躇，甚日酬取？教我怎生忘渠？但愿得一家到此沾禄养，也显得半子从今展孝私。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8225","tags":[]},{"id":"poem-9e7f0c433e35e8d2cde37dde","title":"贺新郎·凤尾龙香拨","author":"辛弃疾","dynasty":"宋","verses":["凤尾龙香拨。","自开元、霓裳曲罢，几番风月。","最苦浔阳江头客，画舸亭亭待发。","记出塞、黄云堆雪。","马上离愁三万里，望昭阳、宫殿孤鸿没。","弦解语，恨难说。","辽阳驿使音尘绝。","琐窗寒、轻拢慢拈，泪珠盈睫。","推手含情还却手，一抹梁州哀彻。","千古事、云飞烟灭。","贺老定场无消息，想沈香亭北繁华歇。","弹到此，为呜咽。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-215","tags":["宋词三百首"]},{"id":"poem-9e7f3f0b3937a055d3c6cc97","title":"郊庙歌辞 武后享清庙乐章十首 第六送文舞","author":"不详","dynasty":"唐","verses":["帝图草创，皇业初开。","功高佐命，业赞云雷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ea6a860c-43d0-4c40-8d6f-e1d3c863dcea","tags":[]},{"id":"poem-9e8189a15214624937c17250","title":"点绛唇·病卧秋风","author":"向子𬤇","dynasty":"宋","verses":["病卧秋风，懒寻杯酒追欢宴。","梦游都甸。","不改当年观。","故旧雕零，天下今无半。","烟尘远。","泪珠零乱。","怕问随阳雁。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-159","tags":[]},{"id":"poem-9e821fa8d2b560a7336b3295","title":"摇柳","author":"孟郊","dynasty":"唐","verses":["弱弱本易惊，看看势难定。","因风似醉舞，尽日不能正。","时邀咏花女，笑辍春妆镜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a00bc423-d9df-47a9-9ac1-cabcaeb5d5bb","tags":[]},{"id":"poem-9e885a60663cad2039fe53b1","title":"闻城哭声有作","author":"佚名","dynasty":"唐","verses":["昨闻河畔哭哀哀，见说分离凡几回。","昔别长男居异域，今殇小子瘗泉台。","覊愁对此肠堪断，客舍闻之心转摧。","漂泊自然无限苦，况复存亡有去来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-a4240a32-199c-479d-8885-12984bfcc0c0","tags":[]},{"id":"poem-9e88d0e5adcb09bdc14c1909","title":"句","author":"裴说","dynasty":"唐","verses":["读书贫里乐，搜句静中忙。","苦吟僧入定，得句将成功。","是事精皆易，唯诗会却难。","因携一家住，赢得半年吟。","吟余潮入浦，坐久烧移山。","三年清似水，六月冷如冰。","一通红锦重，三事紫罗轻。","瘦肌寒带粟，病眼馁生花。","避乱一生多，雪留寒竹寺舍冷。","风撼早梅城郭香，画毬轻蹴壶中地。","彩索高飞掌上身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-678c0799-cd43-43c0-9503-26d4645ff022","tags":[]},{"id":"poem-9e8d8c4350b01239953fca3d","title":"酒泉子·空碛无边","author":"孙光宪","dynasty":"五代","verses":["空碛无边，万里阳关道路。","马萧萧，人去去，陇云愁。","香貂旧制戎衣窄，胡霜千里白。","绮罗心，魂梦隔，上高楼。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-16","tags":[]},{"id":"poem-9ea6010d5de7958c5853d5de","title":"点绛唇·卷尽愁云","author":"吴文英","dynasty":"宋","verses":["卷尽愁云，素娥临夜新梳洗。","暗尘不起。","酥润凌波地。","辇路重来，仿佛灯前事。","情如水。","小楼熏被。","春梦笙歌里。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-194","tags":["宋词三百首"]},{"id":"poem-9ea867e0f15bbb08af8deba4","title":"和常州崔使君寒食夜","author":"沈佺期","dynasty":"唐","verses":["闻道清明近，春闱向夕阑。","行游昼不厌，风物夜宜看。","斗柄更初转，梅香暗里残。","无劳秉华烛，晴月在南端。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6374eebf-a2b0-4dca-82af-9dbe01305e0d","tags":[]},{"id":"poem-9eaec9ce063469916a7e8ef1","title":"河梁晚望二首 二","author":"子兰","dynasty":"唐","verses":["雨添一夜秋涛阔，极目茫茫似接天。","不知龙物潜何处，鱼跃蛙鸣满槛前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-abc03614-423e-45b0-80a0-499d2ce6cca9","tags":[]},{"id":"poem-9eaf347c57c8e0cbcc1f2b1f","title":"答谢建偈（题拟）","author":"彦光","dynasty":"唐","verses":["将知善事多磨，今日碍缘特八。","烦我火头金刚，别告大权菩萨。","（宋调露子《角力记》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f451479b-2d0d-458e-9b32-65067ff26b41","tags":[]},{"id":"poem-9eb0bfbe5e7a8550299c0140","title":"菊花新","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(生上)细思孙二煞无徒，使计藏奸要害吾。","虽然赶出去，遭穷困此身蓝缕。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1799","tags":[]},{"id":"poem-9eb1d09bfce532eeea0677d6","title":"惠尼童子","author":"张祜","dynasty":"唐","verses":["慢眉童子语惺惺，实为天主自有灵。","（「主」，严疑「生」之误。","）可惜绿丝梳黛髻，枉将纤手把铜瓶。","低回綩态传师教，更学吴音诵梵经。","不似俗家诸姊妹，朝朝画得两蛾青。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-34231cba-faf4-4f7a-b513-dfee49d77392","tags":[]},{"id":"poem-9eb3cc0d367a758c92ec18f6","title":"白藕花寄袁状元仓使","author":"释居简","dynasty":"宋","verses":["澄练彻山脉，玉透山池沙。","老火奋残烁，凛姿炖不瑕。","方方秋一奁，弹压红万葩。","安得濂溪叟，来赋东林花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-d81720c9-d8bd-4abc-adc4-8867616c785d","tags":[]},{"id":"poem-9eb6f7f6c1133d6d350acf54","title":"菩萨蛮·榛荆满眼山城路","author":"纳兰性德","dynasty":"清","verses":["榛荆满眼山城路，征鸿不为愁人住。","何处是长安，湿云吹雨寒。","丝丝心欲碎，应是悲秋泪。","泪向客中多，归时又奈何。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-188","tags":[]},{"id":"poem-9eb8028ad5561511919d5b7d","title":"宿府","author":"杜甫","dynasty":"唐","verses":["清秋幕府井梧寒，独宿江城蜡炬残。","永夜角声悲自语，中天月色好谁看。","风尘荏苒音书绝，关塞萧条行路难。","已忍伶俜十年事，强移栖息一枝安。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f540f519-e3c4-41c2-b299-f1d255977705","tags":["唐诗三百首","感时","孤独","七言律诗"]},{"id":"poem-9ec366ee21039e009a738dc0","title":"西塞山怀古","author":"刘禹锡","dynasty":"唐","verses":["西晋楼船下益州，金陵王气黯然收。","千寻铁锁沈江底，一片降旛出石头。","人世几回伤往事，山形依旧枕江流。","今逢四海为家日，故垒萧萧芦荻秋。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-80beb8cc-8338-44d4-8b96-7f9d32133c97","tags":["唐诗三百首","隋・唐・五代","七言律诗","咏史怀古"]},{"id":"poem-9ec4fb9022cacd742763883b","title":"菩萨蛮·花飞零乱随风舞","author":"曹勋","dynasty":"宋","verses":["花飞零乱随风舞。","花梢犹带虚檐雨。","帘幕映黄昏。","江天日暮云。","有人楼上望。","生怕褰虚幌。","冷落对炉薰。","一春常怨春。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-194","tags":[]},{"id":"poem-9ec874e8e692c4200dcb55bf","title":"浣溪沙·水北烟寒雪似梅","author":"毛滂","dynasty":"宋","verses":["水北烟寒雪似梅。","水南梅闹雪千堆。","月明南北两瑶台。","云近恰如天上坐，魂清疑向斗边来。","梅花多处载春回。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-731","tags":[]},{"id":"poem-9ecaa871a74222e75d335523","title":"宿瓜洲寄柳中庸","author":"李端","dynasty":"唐","verses":["怀人同不寐，清夜起论文。","月魄正出海，雁行斜上云。","寒潮来滟滟，秋叶下纷纷。","便送江东去，徘徊祗待君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2213a457-daa0-4b8c-8576-928ab743e4cd","tags":[]},{"id":"poem-9ecf7cc0773941241948829c","title":"浄名二首  其二","author":"米芾","dynasty":"宋","verses":["纵目天容旷，披襟海共开。","山形当槛走，云影度江来。","世界惭双足，生涯付一杯。","横风多景梦，壶领酌泉回。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-82a991e9-fb5d-47fa-978d-bd19796a31a1","tags":[]},{"id":"poem-9edd792a52549371435fbbca","title":"永明山居诗（六十九首） 三十","author":"延寿","dynasty":"唐","verses":["何如深谷一遗人，宴坐经行不累身。","废宅可嗟频换主，凋丛愁见几回春。","尖尖石笑烟笼碧，点点苔钱雨洗新。","堪笑古人非我意，居山多是避强秦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-bcf68588-3c6a-4b3c-814d-0792cf778ae4","tags":[]},{"id":"poem-9ede94570baef8a16ebb0fca","title":"长安少年行 六","author":"李廓","dynasty":"唐","verses":["赏春惟逐胜，大宅可曾归。","不乐还逃席，多狂惯衩衣。","歌人踏日起，语燕卷帘飞。","妇好唯相妬，倡楼不醉稀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4cec2316-98eb-4847-b9e7-afd610e692af","tags":[]},{"id":"poem-9ee3cfd88d8b1be7dc3a2ca3","title":"浣溪沙·藕荡桥边埋钓筒","author":"纳兰性德","dynasty":"清","verses":["藕荡桥边埋钓筒，苎萝西去五湖东。","笔床茶灶太从容。","况有短墙银杏雨，更兼高阁玉兰风。","画眉闲了画芙蓉。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-171","tags":[]},{"id":"poem-9ee5d75f490eec95c6d619ae","title":"咏烛二首 二","author":"太宗皇帝","dynasty":"唐","verses":["九龙蟠燄动，四照逐花生。","即此流高殿，堪持待月明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c3fd8880-154d-479b-a852-c5f31ad5463e","tags":[]},{"id":"poem-9eec609617da5a492faf29ab","title":"寄四明闾丘道士二首 一","author":"贯休","dynasty":"唐","verses":["淮海兵荒日，分飞直至今。","知担诸子出，却入四明深。","衣必编仙草，僧应共栗林。","秋风溪上路，应得一相寻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-771a895b-913a-415f-a75e-8b4112333e61","tags":[]},{"id":"poem-9ef526cd18729c427733cb63","title":"临江仙·尚忆去年称寿日","author":"魏了翁","dynasty":"宋","verses":["尚忆去年称寿日，彩衣犹带天香。","今年还见雁成行。","两头娘子拜，笑领伯仁觞。","知是几年培植底，如今满院芬芳。","只凭方寸答苍苍。","春风来不断，点缀艳阳妆。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-434","tags":[]},{"id":"poem-9f029524711ce2c2101bf7b7","title":"从军行五首 四","author":"皎然","dynasty":"唐","verses":["飞将下天来，奇谋阃外裁。","水心龙劒动，地肺鴈山开。","望气燕师锐，当锋虏阵摧。","从今射雕骑，不敢过云堆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-37cec46c-16fe-40f9-8610-845d552c562f","tags":[]},{"id":"poem-9f0b8b676551cc1cbc104fd7","title":"茅檐","author":"王安石","dynasty":"宋","verses":["茅檐常扫净无苔，花木成蹊手自栽。","一水护田将绿绕，两山排闼送青来。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-茅檐","tags":[]},{"id":"poem-9f0d6b765f6771337cc71c72","title":"甫田","author":"佚名","dynasty":"先秦","verses":["无田甫田，维莠骄骄。无思远人，劳心忉忉。","无田甫田，维莠桀桀。无思远人，劳心怛怛。","婉兮娈兮。总角丱兮。未几见兮，突而弁兮！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-101","tags":[]},{"id":"poem-9f126c62849297740ec8f5e1","title":"寄襄阳王公子","author":"马戴","dynasty":"唐","verses":["君马勒金羁，君家贮玉笄。","白云登岘首，碧树醉铜鞮。","泽广荆州北，山多汉水西。","鹿门知不隐，芳草自萋萋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-73dd12a7-48d8-4b9e-bcac-c07270847304","tags":[]},{"id":"poem-9f24d98ffd831bf53d484872","title":"力疾山下吴邨看杏花十九首 十六","author":"司空图","dynasty":"唐","verses":["潘郎爱说是诗家，枉占河阳一县花。","千载几人搜警句，补方金字爱晴霞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-82d69155-945c-4b35-8730-44b61dd75a13","tags":[]},{"id":"poem-9f365dcbbea98fe54d96dcc5","title":"安居","author":"宋伯仁","dynasty":"宋","verses":["穷通岂在苦劳神，且作安居懒散人。","买地种花多种竹，煮茶邀客也邀邻。","求名岂识书三上，得兴无过醉一巡。","喜得满𥰭收芋栗，杜陵应未笑全贫。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-a4584f90-3036-4fea-b800-ca5b3d1551af","tags":[]},{"id":"poem-9f5f7c05af1963f8fc12d482","title":"咏史诗 巨桥","author":"胡曾","dynasty":"唐","verses":["积粟成尘竟不开，谁知拒谏剖贤才。","武王兵起无人敌，遂作商郊一聚灰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-e202e2ce-5825-4c84-b2fd-5f7ebbb28a52","tags":[]},{"id":"poem-9f7672d1cd1a0f87e5825920","title":"九月十日雨中过张伯佳期柳镇未至以诗招之","author":"李益","dynasty":"唐","verses":["柳吴兴近无消息，张长公贫苦寂寥。","唯有角巾沾雨至，手持残菊向西招。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-9f32abfa-6459-4020-b79d-5f96a026c945","tags":[]},{"id":"poem-9f77d300c31ab53bc3afcaa2","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(旦)才郎意坚牢，才郎意坚牢，贱妾难推调。","只恐容易间，把恩情心事都忘了。","(生)蒋世隆若有此心。","与你星前月下去罚下誓来。","(旦)你自去罚。","(生)蒋世隆若忘了小姐厚恩，永远前程不吉。","海誓山盟，神大须表。","办至诚，图久远同谐老。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2990","tags":[]},{"id":"poem-9f7c7574c93ccca6353e8068","title":"横吹曲辞 洛阳道","author":"于武陵","dynasty":"唐","verses":["浮世若浮云，千回故复新。","旋添青草冢，更有白头人。","岁暮客将老，雪晴山欲春。","行行车与马，不尽洛阳尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ef02ddad-16dc-47e8-b7fc-f5afd4c8c593","tags":[]},{"id":"poem-9f8a19fe0589d266c56b5067","title":"郊庙歌辞 梁太庙乐舞辞 饮福","author":"不详","dynasty":"唐","verses":["戛玉𪭢金永颂声，檿丝孤竹和且清。","灵歆醉止牺象盈，自天降福千万龄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6ef3f8b3-47d4-46fc-a4e6-1e5f5409ca4b","tags":[]},{"id":"poem-9f8ba0014487233a3936b60d","title":"点绛唇·春浪桃花","author":"向子𬤇","dynasty":"宋","verses":["春浪桃花，禹门三尺平跳过。","死生不坐。","变化须归我。","山起南云，白雨声相和。","还知么。","点点真个。","块土何曾破。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-154","tags":[]},{"id":"poem-9f8d127d68c9efb7d0001397","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［丑］你爹娘俱已应承，问侄女缘何不肯？恁推三阻四，莫不是行浊言清。","［旦］枉了将人凌并，便刎下头来，断然不依允。","［丑］论我作伐，宅第尽闻名。","十处说亲九处成，谁学你假惺惺。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8079","tags":[]},{"id":"poem-9f903989d27e42ad873a014a","title":"夏日闲居","author":"张籍","dynasty":"唐","verses":["多病逢迎少，闲居又一年。","药看辰日合，茶过卯时煎。","草长晴来地，虫飞晚后天。","此时幽梦远，不觉到山边。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-6ca8af28-a319-4e0e-95a3-0e757323ebed","tags":[]},{"id":"poem-9f90cf6797097bbdb3e9994a","title":"到宣武三十韵","author":"李绅","dynasty":"唐","verses":["七月趋梁苑，三年谢尹京。","旧风除物蠹，新律奉师贞。","龙节双油重，蛇矛百练明。","跃鱼连后斾，腾虎耀前旌。","路转金神竝，川开铁马横。","拥旄差白羽，分辔引红缨。","在浚风烟接，维嵩巩洛清。","贯鱼奔骑疾，连雁卷行轻。","烟垒风调角，秋原雨洗兵。","宿云看布甲，疎柳见分营。","鼓彻通宵警，和门候晓晴。","虎符三校列，鱼胄万夫迎。","弄马猨猱健，奔车角觝呈。","驾肩傍隘道，张幕内连楹。","森戟承三令，攒戈退一声。","及郊知雨过，观俗辨风行。","望宋怜思女，游梁念客卿。","义夫留感激，公子播英名。","泽广豚鱼洽，恩宣岂弟生。","善师忘任智，中略在推诚。","式宴歌钟合，陈筵绮绣并。","戏鼙千卒跃，均酒百壶倾。","乐与师徒共，欢从井邑盈。","教通因渐染，人悦尚和平。","授钺慙分阃，登坛荷列城。","虚裘朝独坐，雄劒夜孤鸣。","白发侵霜变，丹心捧日惊。","卫青终保志，潘岳未忘情。","期月终迷化，三年讵有成。","惟看波海动，天外斩长鲸。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-438cac15-96b9-4ced-9867-4045458cc672","tags":[]},{"id":"poem-9f927446bcc21db6bbfef746","title":"浣溪沙·桦屋鱼衣柳作城","author":"纳兰性德","dynasty":"清","verses":["桦屋鱼衣柳作城，蛟龙鳞动浪花腥，飞扬应逐海东青。","犹记当年军垒迹，不知何处梵钟声，莫将兴废话分明。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-173","tags":[]},{"id":"poem-9f9300cdea6d3fd4bb825502","title":"新楼诗二十首","author":"李绅","dynasty":"唐","verses":["石桥峰上栖玄鹤，碧阙岩边荫羽人。","冰叶万条垂碧实，玉珠千日保青春。","月中泣露应同浥，涧底侵云尚有尘。","徒使茯苓成琥珀，不为松老化龙鳞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-17ca506f-2af7-4238-a1cf-cf53c4615633","tags":[]},{"id":"poem-9f9cc27d4974fd8cf587f413","title":"檄","author":"李峤","dynasty":"唐","verses":["羽檄本宣明，由来敷木声。","联翩通汉国，迢递入燕营。","毛义持书去，张仪韫璧行。","曹风虽觉愈，陈草始知名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-21dc9c0a-2c78-4268-8d76-58c50cc4c611","tags":[]},{"id":"poem-9fa3086c261cb64729612f1b","title":"题刘处士居","author":"李咸用","dynasty":"唐","verses":["压破岚光半亩余，竹轩兰砌共清虚。","泉经小槛声长急，月过修篁影旋疎。","溪鸟时时窥户牖，山云往往宿庭除。","干戈谩道因天意，渭水高人自钓鱼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-76721884-eab0-4a51-899a-619a410b0fdd","tags":[]},{"id":"poem-9fb09fedf7c8ee85033fc5ef","title":"和张仆射塞下曲 一","author":"卢纶","dynasty":"唐","verses":["鹫翎金仆姑，燕尾绣蝥弧。","独立扬新令，千营共一呼。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-ce491725-b96b-46a7-b83c-463d2094ef3f","tags":["唐诗三百首","将军","乐府","高中古诗","边塞","赞美"]},{"id":"poem-9fb6486cb483cadf52cf6f43","title":"玉泉","author":"纳兰性德","dynasty":"清","verses":["芙蓉殿俯御河寒，残月西风并马看。","十里松杉清绝处，不知晓雪在西山。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-232","tags":[]},{"id":"poem-9fbbeeadd458a88e2d490ab1","title":"奉酬燕公见归田赋垂赠之作","author":"赵冬曦","dynasty":"唐","verses":["穷鸟婴笼缀，孤飞任播迁。","鹪鹩王佐用，复此挫冲天。","楚云何掩郁，湘水亦回邅。","怀哉愧木鴈，忽尔枉兰荃。","愈疾同枚叔，销忧比仲宣。","归途书可畏，弱操石犹坚。","覆载虽云广，涔阳直块然。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-8173fbc6-3427-4723-a388-d974fd193c60","tags":[]},{"id":"poem-9fbfc6c4e389216ec011f011","title":"送宣州丘判官","author":"徐铉","dynasty":"宋","verses":["宪署游从阻，平台道路赊。","喜君驰后乘，于此会仙槎。","缓酌迟飞盖，微吟望绮霞。","相迎在春渚，暂别莫咨嗟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-8eba8c41-0f91-47cd-89de-5fcb023c1e79","tags":[]},{"id":"poem-9fc73afb747eaca1e8f8be1e","title":"姜楚公画角鹰歌","author":"杜甫","dynasty":"唐","verses":["楚公画鹰鹰戴角，杀气森森到幽朔。","观者贪愁掣臂飞，画师不是无心学。","此鹰写真在左緜，却嗟真骨遂虚传。","梁间燕雀休惊怕，亦未抟空上九天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-db1915e5-10c1-40bd-89b7-ea85299fd569","tags":[]},{"id":"poem-9fc8a7eec89fc73f8d5dcbbe","title":"寿阳罢郡日有诗十首与追怀不殊今编于后兼纪瑞物 肥河维舟阻冻袛待勅命 一","author":"李绅","dynasty":"唐","verses":["罢分符竹作闲官，舟冻肥河拟棹难。","食蘗苦心甘处困，饮冰持操敢辞寒。","夜灯空应渔家火，朝食还依雁宿滩。","西奏血诚遥稽首，乞容归病老江干。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-2ac7071c-cfc0-42da-acec-992c1c6b447b","tags":[]},{"id":"poem-9fd169054677e93bf91ad4b2","title":"早起","author":"杨厚","dynasty":"唐","verses":["星汉转寒更，伊余索寞情。","钟催归梦断，雁引远愁生。","危壁兰光暗，疎帘露气清。","闲庭聊一望，海日为分明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-af5c74a2-84a3-4dac-9e4c-c86065f395a2","tags":[]},{"id":"poem-9fed192301b107a6a3e23bf3","title":"送韦十六评事充同谷郡防御判官","author":"杜甫","dynasty":"唐","verses":["昔没贼中时，潜与子同游。","今归行在所，王事有去留。","偪侧兵马间，主忧急良筹。","子虽躯干小，老气横九州。","挺身艰难际，张目视寇雠。","朝廷壮其节，奉诏令参谋。","銮舆驻凤翔，同谷为咽喉。","西扼弱水道，南镇枹罕陬。","此邦承平日，剽劫吏所羞。","况乃胡未灭，控带莽悠悠。","府中韦使君，道足示怀柔。","令姪才俊茂，二美又何求。","受词太白脚，走马仇池头。","古色沙土裂，积阴雪云稠。","羌父豪猪靴，羌儿青兕裘。","吹角向月窟，苍山旌旆愁。","鸟惊出死树，龙怒拔老湫。","古来无人境，今代横戈矛。","伤哉文儒士，愤激驰林丘。","中原正格鬬，后会何缘由。","百年赋命定，岂料沈与浮。","且复恋良友，握手步道周。","论兵远壑净，亦可纵冥搜。","题诗得秀句，札翰时相投。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-76fbf9e9-5941-4a96-a62f-fd66183dfe38","tags":[]},{"id":"poem-9fef1f3da628da92f89b365f","title":"着","author":"佚名","dynasty":"先秦","verses":["俟我于着乎而，充耳以素乎而，尚之以琼华乎而。","俟我于庭乎而，充耳以青乎而，尚之以琼莹乎而。","俟我于堂乎而，充耳以黄乎而，尚之以琼英乎而。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-97","tags":[]},{"id":"poem-9fefb9c3a70d89e5e4fe184e","title":"及第后读书院咏物[一]十首上礼部李侍郎 药臼[一]","author":"樊铸","dynasty":"唐","verses":["器重性仍坚，登庸响即传。","口因良药苦，心为中规圆。","继务精三代，轮攻孕十全。","终齐善救理，莫谓枉陶甄。","（[一]刘云：「『臼』与『救』同，声为上去，故可作音源。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-682bdadf-8d41-40a1-9c70-f6b6bee6c279","tags":[]},{"id":"poem-9ff1ec882ea8fa6220dd23d7","title":"春梦","author":"王镃","dynasty":"宋","verses":["东风敲碎玉阑干，蝴蝶纷飞梦欲残。","翠被压床银烛暗，夜深谁问海棠寒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-9fec99d9-fdcb-4f11-be79-b2e9f268cd28","tags":[]},{"id":"poem-9ffe156f5277c052c736841c","title":"渔家傲·名利场中空扰扰","author":"高登","dynasty":"宋","verses":["名利场中空扰扰。","十年南北东西道。","依旧缘山尘扑帽。","空懊恼。","羡他陶令归来早。","归去来兮秋已杪。","菊花又绕东篱好。","有酒一尊开口笑。","虽然老。","玉山犹解花前倒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-233","tags":[]},{"id":"poem-a00462fe2ee731cf2ccd50b7","title":"江行纪事二首 一","author":"席豫","dynasty":"唐","verses":["飘飖任舟楫，回合傍江津。","后浦情犹在，前山赏更新。","树深烟幂幂，滩浅石磷磷。","川路南行远，淹留惜此辰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-b09794a8-da3c-473b-939c-a9c8687def73","tags":[]},{"id":"poem-a009ac0b11f7929bfc7ad59f","title":"沁园春·春事阑斑","author":"吴泳","dynasty":"宋","verses":["春事阑斑，桐花烂漫，不堪凤栖。","叹交枰世道，容容是福，危航宦海，了了成痴。","邵子豪情，乐天狂态，六十六年才觉非。","溪山畔，要看承风月，舍我其谁。","文章高下随时。","料织锦应须用锦机。","愧老无健笔，高凌月胁，病无佳句，下解人颐。","君昔东坡，我今韩愈，造化一炉如小儿。","都休管，看龟翻荷露，燕落芹泥。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-573","tags":[]},{"id":"poem-a00b704c53d9091020e20c00","title":"白苎歌","author":"释居简","dynasty":"宋","verses":["经纱才上机，梭飞玉攕攕。","怕君寻春迟，落机宽裁衫。","春心乱如蓬，冉冉随春霏。","芳迳晓沾露，软尘红上衣。","归来恨尘污，湔衣浣纱处。","难湔芳露痕，易湔衣上尘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-37c7343c-b1b0-4d27-952d-7aea9c2d3de5","tags":[]},{"id":"poem-a01646d0b8691bc04636707b","title":"过锦湾望岳亭","author":"燮元圃","dynasty":"宋","verses":["十载重来一凭栏，光阴不改旧江山。","亭高下瞰龙藏室，天远遥瞻虎拜班。","耕钓每怀生处乐，驰驱未许老来闲。","雄风入座披襟好，静看渔舟上锦湾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-86a90c39-7d1f-41d4-84ce-34357c67a8f6","tags":[]},{"id":"poem-a02253463b7846308bc9743b","title":"浣溪沙·姜女庙","author":"纳兰性德","dynasty":"清","verses":["海色残阳影断霓，寒涛日夜女郎祠。","翠钿尘网上蛛丝。","澄海楼高空极目，望夫石在且留题。","六王如梦祖龙非。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-43","tags":[]},{"id":"poem-a026d42ecb024f2e1f8d826e","title":"哭栖白供奉","author":"李洞","dynasty":"唐","verses":["闻说孤窗坐化时，白莎萝雨滴空池。","吟诗堂里秋关影，礼佛灯前夜照碑。","贺雪已成金殿梦，看涛终负石桥期。","逢山对月还惆怅，争得无言似祖师。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-1eeb7ca0-1fc0-4dfa-94ca-f496d5f3eab6","tags":[]},{"id":"poem-a02b5913c7884caf04a2d881","title":"答刘明府","author":"张籍","dynasty":"唐","verses":["身病多时又客居，满城亲旧尽相疎。","可怜绛县刘明府，犹解频频寄远书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-3ab2c0eb-e8e5-4b84-bf00-60a49887ac0c","tags":[]},{"id":"poem-a030dd1db8be1e493b29db23","title":"山中寄姚合员外","author":"马戴","dynasty":"唐","verses":["朝与城阙别，暮同麋鹿归。","鸟鸣松观静，人过石桥稀。","木叶摇山翠，泉痕入涧扉。","敢招仙署客，暂此拂朝衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-2e1fce4c-ec2a-43db-b972-4f362dab2f6b","tags":[]},{"id":"poem-a05368847d89f6963587a85d","title":"别一章改韵同五诗呈尧夫","author":"司马光","dynasty":"宋","verses":["家虽在城阙，萧瑟似山阿。","远去名利窟，自称安乐窝。","云归白石洞，鹤立碧松柯。","得丧非吾事，何须更寤歌。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-1409bc46-771c-4675-ba3b-fd6f10fbb9be","tags":[]},{"id":"poem-a054c186b3524de62f531c04","title":"和范秘书宿省中作","author":"喻坦之","dynasty":"唐","verses":["清省宜寒夜，仙才称独吟。","钟来宫转漏，月过合移阴。","鹤避灯前尽，芸高幄外深。","想知因此兴，暂动忆山心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-bdeeb316-5a01-432c-93f0-ef4bffe37469","tags":[]},{"id":"poem-a0555dc1bb591b47b00718ee","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(末、丑)兄寻妹，涕泪涟。","忽听得悠悠声应远，只道是妹见哥哥，却原来错认陶潜。","那女子呵，他娘儿拆散中途畔，叫声应声随呼唤。","(外)那女子怎么应他？(末、丑)那女子叫名瑞兰，与瑞莲声音厮类。","名韵相同事偶然。","(外)那女子失散了母亲，在途路上单身不便了。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3098","tags":[]},{"id":"poem-a05920e9ec8aecb56ba97e80","title":"永明山居诗（六十九首） 二十八","author":"延寿","dynasty":"唐","verses":["急景韶颜不可追，岂堪回首暂思之。","浮云已断平生望，高节须存往日期。","庭树任猿偷熟果，崖松停鹤惜高枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-74fb9b4d-3281-408a-a099-4d10b06f681a","tags":[]},{"id":"poem-a062ac1db36bc5d7fa83bb44","title":"明皇游月宫歌","author":"赵文","dynasty":"宋","verses":["铁龙一掷九万里，银桥冉冉行秋水。","霓裳不是世间音，只有嫦娥似妃子。","恍然一梦酒初醒，依然玉座云母屏。","明朝写出天上曲，却笑羯鼓羊皮腥。","人间万事如秋草，离别苦多欢乐少。","崎岖万里锦官城，此身曾作银桥行。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-bc58d0db-f367-47f3-8674-4963ec06ff0c","tags":[]},{"id":"poem-a06682e0d21c76ffdc17cdb5","title":"溪涨","author":"杜甫","dynasty":"唐","verses":["当时浣花桥，溪水才尺余。","白石明可把，水中有行车。","秋夏忽泛溢，岂惟入吾庐。","蛟龙亦狼狈，况是鼈与鱼。","兹晨已半落，归路跬步疎。","马嘶未敢动，前有深填淤。","青青屋东麻，散乱床上书。","不意远山雨，夜来复何如。","我游都市间，晚憩必邨墟。","乃知久行客，终日思其居。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2284b2b3-acf3-4bb9-b736-de901b0967f9","tags":[]},{"id":"poem-a06981abf2254fe9250e7874","title":"诉衷情·露莲双脸远山眉","author":"晏殊","dynasty":"宋","verses":["露莲双脸远山眉。","偏与淡妆宜。","小庭帘幕春晚，闲共柳丝垂。","人别后，月圆时。","信迟迟。","心心念念，说尽无凭，只是相思。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-496","tags":[]},{"id":"poem-a06c5dd65a8fdf339dba3ff8","title":"三年冬大礼五首 五","author":"曹唐","dynasty":"唐","verses":["太和琴暖发南薰，水阔风高得细闻。","沧海举歌夔是相，历山回禅舜为君。","翠微呼处生丹障，清静封中起白云。","今日病身慙小隐，欲将泉石勒移文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f8b618be-e9b4-48aa-8408-f626a6737e7b","tags":[]},{"id":"poem-a0709d151c8a74480a1ab7b7","title":"采桑子·凉生露气湘弦润","author":"纳兰性德","dynasty":"清","verses":["凉生露气湘弦润，暗滴花梢。","帘影谁摇，燕蹴风丝上柳条。","舞鹍镜匣开频掩，檀粉慵调。","朝泪如潮，昨夜香衾觉梦遥。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-94","tags":[]},{"id":"poem-a076e84ed605fdbd17e3182e","title":"九歌·湘君","author":"屈原","dynasty":"先秦","verses":["君不行兮夷犹，蹇谁留兮中洲。","美要眇兮宜修，沛吾乘兮桂舟。","令沅湘兮无波，使江水兮安流。","望夫君兮未来，吹参差兮谁思。","驾飞龙兮北征，邅吾道兮洞庭。","薜荔柏兮蕙绸，荪桡兮兰旌。","望涔阳兮极浦，横大江兮扬灵。","扬灵兮未极，女婵媛兮为余太息。","横流涕兮潺湲，隐思君兮陫侧。","桂棹兮兰枻，斵冰兮积雪。","采薜荔兮水中，搴芙蓉兮木末。","心不同兮媒劳，恩不甚兮轻绝。","石濑兮浅浅，飞龙兮翩翩。","交不忠兮怨长，期不信兮告余以不闲。","朝骋骛兮江皋，夕弭节兮北渚。","鸟次兮屋上，水周兮堂下。","捐余玦兮江中，遗余佩兮醴浦。","采芳洲兮杜若，将以遗兮下女。","时不可兮再得，聊逍遥兮容与。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-3","tags":[]},{"id":"poem-a07f1a373d2d16ed8b5e6f6e","title":"浣溪沙·睡起惺忪强自支","author":"纳兰性德","dynasty":"清","verses":["睡起惺忪强自支。","绿倾蝉鬓下帘时。","夜来愁损小腰肢。","远信不归空伫望，幽期细数却参差。","更兼何事耐寻思。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-27","tags":[]},{"id":"poem-a086750499eb34f82afa06df","title":"芳洲泊・踏莎行·露叶栖萤","author":"贺铸","dynasty":"宋","verses":["露叶栖萤，风枝袅鹊。","水堂离燕褰珠箔。","一声横玉吹流云，厌厌凉月西南落。","江际吴边，山侵楚角。","兰桡明夜芳洲泊。","殷勤留语采香人，清尊不负黄花约。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-96","tags":[]},{"id":"poem-a09207d3b1e31f43dbfc39a3","title":"和修睦上人听猿","author":"李咸用","dynasty":"唐","verses":["禅客闻犹苦，是声应是啼。","自然无稳梦，何必到巴溪。","疎雨洒不歇，回风吹暂低。","此宵秋欲半，山在二林西。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-99d23371-41cb-4840-b6b2-4ee068cb1a4d","tags":[]},{"id":"poem-a0927193812a6c2c68901f65","title":"郊庙歌辞 后唐宗庙乐舞辞 武成舞","author":"崔居俭、卢文纪","dynasty":"唐","verses":["艰难王业，返正皇唐。","先天再造，却日重光。","汉绍世祖，夏资少康。","功成德茂，率祀无疆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6efdeafd-8fbd-40a2-83f3-7a570f43a2e8","tags":[]},{"id":"poem-a097c2357cffa556e3a4bc5b","title":"人日重宴大明宫赐彩缕人胜应制","author":"沈佺期","dynasty":"唐","verses":["拂旦鸡鸣仙衞陈，凭高龙首帝城春。","千官黼帐杯前寿，百福香匳胜里人。","山鸟初来犹怯啭，林花未发已偷新。","天文正应韶光转，设报悬知用此辰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0d7195e8-759e-494d-9b4e-3aa59a3693a8","tags":[]},{"id":"poem-a099303112bd7a4e3a58f26d","title":"句 一","author":"徐铉","dynasty":"唐","verses":["落月依楼阁，归云拥殿廊。","（《宿山寺》，见《宋诗纪事》引宋释文莹《玉壶野史》。","）（见《玉壶清话》卷八。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-99296779-2df5-4d76-b1b0-c87f0bfbd95b","tags":[]},{"id":"poem-a09d6a4ec471a615b412584c","title":"更漏子 其六","author":"温庭筠","dynasty":"唐","verses":["玉炉香，红蜡泪，偏照画堂秋思。","眉黛薄，鬓云残，夜长衾枕寒。","梧桐树，三更雨，不道离情正苦。","一叶叶，一声声，空阶滴到明。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-19","tags":[]},{"id":"poem-a09f406be038aec2ed1461bd","title":"思佳客·不肯楼边著画船","author":"高观国","dynasty":"宋","verses":["不肯楼边著画船。","载将诗酒入风烟。","浪花溅白疑飞鹭，荷芰藏红似小莲。","醒醉梦，唤吟仙。","先秋一叶莫惊蝉。","白云乡里温柔远，结得清凉世界缘。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-382","tags":[]},{"id":"poem-a0a61f9c9d2ce76b77db0289","title":"登润州芙蓉楼","author":"崔峒","dynasty":"唐","verses":["上古人何在，东流水不归。","往来潮有信，朝暮事成非。","烟树临沙静，云帆入海稀。","郡楼多逸兴，良牧谢玄晖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-8ea76149-dd97-4cd4-9564-7595c9df1506","tags":[]},{"id":"poem-a0aa11fe6417f9a8d704aa5c","title":"句","author":"李洞","dynasty":"唐","verses":["公道此时如不得，昭陵恸哭一生休。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-fc3945f6-f7a7-434c-adc5-fe0b2043d17d","tags":[]},{"id":"poem-a0ac7028c6caed778d128254","title":"寻僧二首 二","author":"赵嘏","dynasty":"唐","verses":["溪户无人谷鸟飞，石桥横木挂禅衣。","看云日暮倚松立，野水乱鸣僧未归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-6a06afff-5756-4039-99c3-9c471a29613b","tags":[]},{"id":"poem-a0b067562d95e7ad042a03b9","title":"赠陶山人","author":"刘得仁","dynasty":"唐","verses":["处士例营营，惟君纵此生。","闲能资寿考，健不换公卿。","药圃妻同耨，山田子共耕。","定知丹熟后，无姓亦无名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-d145d16f-5c47-40d0-9b2e-a8ad34ef40e9","tags":[]},{"id":"poem-a0b9cd72f5a6e7943a8f8232","title":"更漏子·雪肌轻","author":"杜安世","dynasty":"宋","verses":["雪肌轻，花脸薄。","愁困不忺梳掠。","眉翠袅，眼波长。","偎人言语香。","看难厌，怜不足。","苦恨别离何速。","珠树远，彩鸾孤。","今生重见无。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-900","tags":[]},{"id":"poem-a0baeaec4799e1be98c735ff","title":"九思·哀岁","author":"王逸","dynasty":"汉","verses":["旻天兮清凉，玄气兮高朗。","北风兮潦洌，草木兮苍唐。","蛜蚗兮噍噍，蝍蛆兮穰穰。","岁忽忽兮惟暮，余感时兮凄怆。","伤俗兮泥浊，蒙蔽兮不章。","宝彼兮沙砾，捐此兮夜光。","椒瑛兮湟污，葈耳兮充房。","摄衣兮缓带，操我兮墨阳。","升车兮命仆，将驰兮四荒。","下堂兮见虿，出门兮触螽。","巷有兮蚰蜓，邑多兮螳螂。","睹斯兮嫉贼，心为兮切伤。","俛念兮子胥，仰怜兮比干。","投剑兮脱冕，龙屈兮蜿蟤。","潜藏兮山泽，匍匐兮丛攒。","窥见兮溪涧，流水兮沄沄。","鼋鼍兮欣欣，鳣鲇兮延延。","群行兮上下，骈罗兮列陈。","自恨兮无友，特处兮茕茕。","冬夜兮陶陶，雨雪兮冥冥。","神光兮颎颎，鬼火兮荧荧。","修德兮困控，愁不聊兮遑生。","忧纡兮郁郁，恶所兮写情。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-63","tags":[]},{"id":"poem-a0c08c9eb5231e0f091e4d38","title":"春燕词","author":"王建","dynasty":"唐","verses":["新燕新燕何不定，东家绿池西家井。","飞鸣当户影悠扬，一遶簷头一遶梁。","黄姑说向新妇女，去年堕子污衣箱。","已能辞山复过海，幸我堂前故巢在。","求食慎勿爱高飞，空中饥鸢为尔害。","辛勤作窠在画梁，愿得年年主人富。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-4b18fd37-f900-44bc-86a6-84243776001f","tags":[]},{"id":"poem-a0c3987853e53dc1e1d174b3","title":"杨柳枝·金缕毵毵碧瓦沟","author":"温庭筠","dynasty":"唐","verses":["金缕毵毵碧瓦沟，六宫眉黛惹香愁。","晚来更带龙池雨，半拂栏干半入楼。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-32","tags":[]},{"id":"poem-a0ce60a43160ab55139885ce","title":"临江仙·南齐天子宠婵娟","author":"毛熙震","dynasty":"五代","verses":["南齐天子宠婵娟，六宫罗绮三千。","潘妃娇艳独芳妍，椒房兰洞，云雨降神仙。","纵态迷欢心不足，风流可惜当年。","纤腰婉约步金莲，妖君倾国，犹自至今传。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-40","tags":[]},{"id":"poem-a0d2747d41b6bfe1b789ef15","title":"鹧鸪天·一点残红欲尽时","author":"周紫芝","dynasty":"宋","verses":["一点残红欲尽时。","乍凉秋气满屏帏。","梧桐叶上三更雨，叶叶声声是别离。","调宝瑟，拨金猊。","那时同唱鹧鸪词。","如今风雨西楼夜，不听清歌也泪垂。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-272","tags":["宋词三百首"]},{"id":"poem-a0d80e9080020995894fac0f","title":"赋罗汉果","author":"张栻","dynasty":"宋","verses":["黄实累累本自芳，西湖名字著诸方。","里称胜母吾常避，珍重山僧自煮汤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-d5895440-9441-44bd-9887-6f166ff568a8","tags":["西湖"]},{"id":"poem-a0ed52869fd3829b356b9193","title":"陪楚州韦舍人北阊门游宴","author":"张祜","dynasty":"唐","verses":["柘岸齐空远，通波跨槛牢。","四方人意便，两路马行高。","雾柳蒙疎叶，风帆挂并艘。","碧云秋水静，红日暮霞韬。","苟藉公心度，稀逢敏手操。","旧恩重雨露，新命压波涛。","挹海惊涯涘，冲霄讶羽毛。","丝纶初变体，锦袖旋挥毫。","美景尤难卜，良辰不易遭。","名华应独步，语韵洽朋曹。","异日知司衮，闲时解梦刀。","卿材尊宦达，侯业重人豪。","拽盏怜稀饮，扶鞍哂遽逃。","香凫深促坐，画鹢远回篙。","赌气连呼采，縻心乍漱醪。","俣妨孤愤激，肯忘一言褒。","北阙承优话，南方续广骚。","不尝书咄咄，谁话酒陶陶。","末路犹提笔，雄藩伫拥旄。","只愁迂蹇步，归去又蓬蒿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-31cba378-c223-40d2-b9cf-811018999cf3","tags":[]},{"id":"poem-a0eed750f8f251ceabbe8cb4","title":"偈颂七十一首  其四六","author":"释了惠","dynasty":"宋","verses":["虎生三子尾咤沙，咂舌垂涎弄爪牙。","但见威风起岩窦，不知月照几千家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-8be4a32d-a4fd-49ec-8777-8b0f79307dc8","tags":[]},{"id":"poem-a0f0fd88dc078c7030ec9e32","title":"送别陈侍郎应求知泉州","author":"林光朝","dynasty":"宋","verses":["百片牙旗水面长，蔡邕题在刺桐乡。","十年杯酒开云榭，一样官衔过洛阳。","我亦携家缘送客，谁能扫地自焚香。","野桥冲腊寒梅白，莫要登临忆侍郎。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-aa5723c4-7ec9-4cd7-9b07-1b6453828ef4","tags":[]},{"id":"poem-a0f262e638c03803cc5d9095","title":"紫苏丸","author":"无名氏《张协状元》","dynasty":"元","verses":["蓬莱路不远，两情休怨夤缘浅。","只听得丝竹管弦声，料今宵得遂鸳鸯愿。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2742","tags":[]},{"id":"poem-a0fdb44c76e00381bafe9032","title":"句","author":"明皇帝","dynasty":"唐","verses":["昔见漳滨卧，言将人事违。","今逢庆诞日，犹谓学仙归。","棠棣花重发，鸰原鸟再飞。","德比代云布，心如晋水清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-63e5f845-6aac-4453-9bc0-23b81643aebd","tags":[]},{"id":"poem-a100966bbf4874a8065edafe","title":"北曲折桂令","author":"萧德祥《小孙屠》","dynasty":"元","verses":["几回价守定香闺，转无眠情绪如痴。","直哭得绛蜡烟消，银蟾影坠，宝篆香微。","才听得促织儿声沉四壁，又听得叫残早报晓邻鸡。","只影孤凄，心下伤悲。","一弄儿凄凉，总促在愁眉。","(又唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8615","tags":[]},{"id":"poem-a100ea969007cc4d384f6315","title":"烛影摇红·双阙中天","author":"张抡","dynasty":"宋","verses":["双阙中天，凤楼十二春寒浅。","去年元夜奉宸游，曾侍瑶池宴。","玉殿珠帘尽卷。","拥群仙、蓬壶阆苑。","五云深处，万烛光中，揭天丝管。","驰隙流年，恍如一瞬星霜换。","今宵谁念泣孤臣，回首长安远。","可是尘缘未断。","谩惆怅、华胥梦短。","满怀幽恨，数点寒灯，几声归雁。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-59","tags":["宋词三百首"]},{"id":"poem-a1099ebd4b3474803f6bcafd","title":"踏莎行·雨霁风光","author":"欧阳修","dynasty":"宋","verses":["雨霁风光，春分天气。","千花百卉争明媚。","画梁新燕一双双，玉笼鹦鹉愁孤睡。","薜荔依墙，莓苔满地。","青楼几处歌声丽。","蓦然旧事心上来，无言敛皱眉山翠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-617","tags":[]},{"id":"poem-a11051b7055a5b2c3995d2a4","title":"到家","author":"宋伯仁","dynasty":"宋","verses":["尘压征裘满，今朝喜到家。","牵衣儿欲泪，满地菊初花。","瓦甑添蒸芋，铜铛旋煮茶。","安贫儒者事，何必恋天涯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-ea0e8313-6445-4b5c-bc54-3ba4e7bdede0","tags":[]},{"id":"poem-a11a0bd454ed321a268f4c65","title":"锦天乐","author":"萧德祥《小孙屠》","dynasty":"元","verses":["且停威，告恩官略慈念。","昨日我萱亲去烧香，卑人送到半途回转。","谁把我妻谋骗？首级无有鲜血染，望恩官乞赐明验。","回心转，言念无辜，怎生屈受刑宪？(又唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8640","tags":[]},{"id":"poem-a11d5abd47e7b55b50ec3ae9","title":"题麻姑山庙","author":"李翔","dynasty":"唐","verses":["险翠峨霄压上游，大仙曾向此幽求。","云埋三级坛空在，月照千寻水自流。","偃盖鹤还清露滴，古池龙睡碧莲秋。","桑田未必翻为海，香火何人解继修。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-67aaf6ce-ab3a-4b12-87b9-8cc998c5f223","tags":[]},{"id":"poem-a12909ea6f69fa488976574a","title":"玉蝴蝶·春欲尽","author":"孙光宪","dynasty":"五代","verses":["春欲尽，景仍长，满园花正黄。","粉翘两悠飏，翩翩过短墙。","鲜飙暖，牵游伴，飞去立残芳。","无语对萧娘，舞衫沉麝香。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-31","tags":[]},{"id":"poem-a12cbae701a2d9cfd6a6c491","title":"丝衣","author":"佚名","dynasty":"先秦","verses":["丝衣其紑，载弁俅俅。自堂徂基，自羊徂牛，鼐鼎及鼒，兕觥其觩。旨酒思柔。不吴不敖，胡考之休。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-291","tags":[]},{"id":"poem-a12ed88b2b1579be0f3b4d72","title":"题李山人幽居","author":"张籍","dynasty":"唐","verses":["襄阳南郭外，茅屋一书生。","无事焚香坐，有时寻竹行。","画苔藤杖细，踏石笋鞋轻。","应笑风尘客，区区逐世名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b96f1531-8af5-4481-8e9a-669721f8d5a7","tags":[]},{"id":"poem-a1353bc650a91b4a27e70570","title":"庐山独夜","author":"徐凝","dynasty":"唐","verses":["寒空五老雪，斜月九江云。","钟声知何处，苍苍树里闻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-d346c4dc-4c39-45bc-ac89-33f0a917781e","tags":["庐山"]},{"id":"poem-a13550f9bf77c416d4ea5d13","title":"句","author":"何兆","dynasty":"唐","verses":["芙蓉十二池心漏，薝卜三千灌顶香。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a8cb3dc3-f809-4681-907c-49afb54f3015","tags":[]},{"id":"poem-a135ba8874e9b8fea6dab622","title":"游徐城河忽见清淮因寄赵八","author":"李嘉祐","dynasty":"唐","verses":["自缘迟暮忆沧洲，翻爱南河浊水流。","初过重阳惜残菊，行看旧浦识群鸥。","朝霞映日同归处，暝柳摇风欲别秋。","长恨相逢即分首，含情掩泪独回头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-36128fe1-a9f6-4841-99a6-9b7995ac94d3","tags":[]},{"id":"poem-a14282caf723d7769708391b","title":"菩萨蛮·玉楼冰簟鸳鸯锦","author":"牛峤","dynasty":"五代","verses":["玉楼冰簟鸳鸯锦，粉融香汗流山枕。","帘外辘轳声，敛眉含笑惊。","柳阴烟漠漠，低鬓蝉钗落。","须作一生拌，尽君今日欢。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-20","tags":[]},{"id":"poem-a1433093342feff09ab5333e","title":"天仙子·踯躅花开红照水","author":"皇甫松","dynasty":"唐","verses":["踯躅花开红照水，鹧鸪飞绕青山觜。","行人经岁始归来，千万里，错相倚，懊恼天仙应有以。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-17","tags":[]},{"id":"poem-a151dd611547c2d15f6d90fd","title":"题山中故静禅师","author":"刘得仁","dynasty":"唐","verses":["寂灭身何在，门人隔此生。","影悬尘已厚，塔种柏初成。","溪院秋先雪，山堂古有精。","当时挂锡处，树老几枝倾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e90dab5d-7bd8-4253-97ae-c324cc38a5a1","tags":[]},{"id":"poem-a159fc43f613c9541cb86a00","title":"酒泉子·连面霜风","author":"曹勋","dynasty":"宋","verses":["连面霜风。","野馆山村逢至日，开怀欲𣨼酒杯空。","与谁同。","一缄来信托飞鸿。","信里催归无限意，黄昏应是出房栊。","夜香浓。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-154","tags":[]},{"id":"poem-a15a216656172868ad48fb2f","title":"月云高","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["路途劳倦，行行甚时近？未到得洛阳县，那盘缠使尽。","回首孤坟，空教我望孤影。","他那里谁秋采？俺这里将谁投奔？正是西出阳关无故人，须信道家贫不是贫。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5184","tags":[]},{"id":"poem-a15b9bed7ed1934750c1ad9c","title":"孤雁儿・御街行·藤床纸帐朝眠起","author":"李清照","dynasty":"宋","verses":["藤床纸帐朝眠起。","说不尽、无佳思。","沈香断续玉炉寒，伴我情怀如水。","笛里三弄，梅心惊破，多少春情意。","小风疏雨萧萧地。","又催下、千行泪。","吹箫人去玉楼空，肠断与谁同倚。","一枝折得，人间天上，没个人堪寄。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-676","tags":[]},{"id":"poem-a15e8efd08316a3746f8dc9c","title":"龙门","author":"杜甫","dynasty":"唐","verses":["龙门横野断，驿树出城来。","气色皇居近，金银佛寺开。","往还时屡改，川水日悠哉。","相阅征途上，生涯尽几回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-aa5d85b7-f78f-4be4-9419-8453c46dd842","tags":[]},{"id":"poem-a166859519fe2e599f90d59e","title":"寄王平江侍郎  其一","author":"释居简","dynasty":"宋","verses":["在御无弦别有音，音中逸响岂难寻。","一弹首詟乘轩贵，万古群空立仗瘖。","肆狡缺唇安夜穴，凭妖九尾远城阴。","双旌不驻夫差国，谁振延陵季子心。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-2b37b4dd-f049-4217-bf90-68d52d1b32f7","tags":[]},{"id":"poem-a166de1dd2de8e29372adc4f","title":"效赵学士体成口号十章献开府太师  其七","author":"司马光","dynasty":"宋","verses":["东田小籍选新声，歌吹胡琴色色精。","客少有时全不用，天然水竹湛余清。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-a8042dbd-72fd-4286-934a-09a94a67e7b3","tags":[]},{"id":"poem-a16d338eff5dca5e8b603732","title":"兵要望江南 《周易》占候第二十六（三十七首） 十四","author":"易静","dynasty":"唐","verses":["占贼信，应动是（辛本、川本作「世」）为他。","其贼来时须（辛本、川本作「虽」）是到，到时攻我将须拿，来将丧黄沙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f9b8d9ee-4fe8-4057-92bb-7c16b14c1df4","tags":[]},{"id":"poem-a1714355eb7c64c614f63e7b","title":"次大人二月三日过吴德仁韵二首  其一","author":"刘跂","dynasty":"宋","verses":["溪上高人称福吴，一尊深喜共为娱。","步行可是困公子，日晏不应骄灌夫。","纵履全胜驱下泽，缓歌长欲听提壶。","行年八十心如水，正觉公非嵇阮徒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-6fc38d76-f825-46a4-850b-b3471fcbb3fb","tags":[]},{"id":"poem-a17cb114037072132035a45d","title":"疏影急","author":"刘唐卿《白兔记》","dynasty":"元","verses":["祥光影里，见宫殿尽是金装玉砌。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8809","tags":[]},{"id":"poem-a182d7399e98973fd5bd9079","title":"菀柳","author":"佚名","dynasty":"先秦","verses":["有菀者柳，不尚息焉。上帝甚蹈，无自暱焉。俾予靖之，后予极焉。","有菀者柳，不尚愒焉。上帝甚蹈，无自瘵焉。俾予靖之，后予迈焉。","有鸟高飞，亦傅于天。彼人之心，于何其臻。曷予靖之，居以凶矜。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-223","tags":[]},{"id":"poem-a18df54322299ce715cb2e9f","title":"沁园春·浓绿交阴","author":"曹勋","dynasty":"宋","verses":["浓绿交阴，脆圆经雨，夏景正新。","遽紫泥封检，红幢建钺，飘然吹起，一片闲云。","禁殿趋班，玉音亲诏，并遣皇华通宝邻。","凌歊去，任重霄温暑，万里风薰。","炎曦正斡天钧。","更午气均齐天地根。","运至精感化，千和万合，涤堤旁说，必自成真。","已约归期，秋风前后，梨枣黄花满地匀。","阊阖晚，待朝元紫府，上达明君。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-191","tags":[]},{"id":"poem-a192db6179597ee632cf3fd6","title":"赠内人","author":"张祜","dynasty":"唐","verses":["禁门宫树月痕过，媚眼唯看宿燕窠。","斜拔玉钗灯影畔，剔开红焰救飞蛾。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-84bd91bd-11f7-4218-b9e2-b05b06ce8b99","tags":["唐诗三百首","七言绝句","宫怨","女子"]},{"id":"poem-a19cd58aba442839d8701856","title":"过吴门二十四韵","author":"李绅","dynasty":"唐","verses":["烟水吴都郭，阊门架碧流。","绿杨深浅巷，青翰往来舟。","朱户千家室，丹楹百处楼。","水光摇极浦，草色辨长洲。","忆作麻衣翠，曾为旅棹游。","放歌随楚老，清宴奉诸侯。","花寺听莺入，春湖看雁留。","里吟传绮唱，乡语认歈讴。","桥转攒虹饮，波通鬬鹢浮。","竹扉梅圃静，水巷橘园幽。","缝堵荒麋苑，穿岩破虎丘。","旧风犹越鼓，余俗尚吴钩。","故馆曾闲访，遗基亦徧搜。","吹台山木尽，香径佛宫秋。","帐殿菰蒲掩，云房露雾收。","苎萝妖覆灭，荆棘鬼包羞。","风月俄黄绶，经过半白头。","重来冠盖客，非复别离愁。","候火分通陌，前旌驻外邮。","水风摇彩斾，堤柳引鸣驺。","问吏儿孙隔，呼名礼敬修。","顾瞻殊宿昔，语默过悲忧。","义感心空在，容衰日易偷。","还持沧海诏，从此布皇猷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-fac21232-f8fd-4b2f-8e72-c794307ba356","tags":[]},{"id":"poem-a19fd798b5d5236aaff6acf8","title":"入鬼门关","author":"沈佺期","dynasty":"唐","verses":["昔传瘴江路，今到鬼门关。","土地无人老，流移几客还。","自从别京洛，颓鬓与衰颜。","夕宿含沙里，晨行冈路间。","马危千仞谷，舟险万重湾。","问我投何地？西南尽百蛮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d46c4f3d-5cf0-429c-af46-b233f3495bd1","tags":[]},{"id":"poem-a1b3df79f63cfa50b6f06f41","title":"颂古三十一首  其六","author":"释原妙","dynasty":"宋","verses":["杀人犹可恕，再犯岂能容。","贬向无生国，千圣不知踪。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-026b9261-856a-4ce2-ab2d-f181a18e16ea","tags":[]},{"id":"poem-a1c0d485c09d444437ec40ba","title":"清平乐·花边柳际","author":"谢逸","dynasty":"宋","verses":["花边柳际。","已渐知春意。","归信不知何日是。","旧恨欲拚无计。","故人零落西东。","题诗待倩归鸿。","惟有多情芳草，年年处处相逢。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-626","tags":[]},{"id":"poem-a1c15e3c82e7116e2425987a","title":"丘林诸君以春雪三绝见寄走赋长句奉酬","author":"苏颂","dynasty":"宋","verses":["彼美春工用意多，剪裁琼蕊缀庭柯。","妍辞重识梁园赋，寡和还推郢国歌。","莫叹余花皆惨悴，共看修柏自婆娑。","尊前谩爱风光好，不见山阴泛棹过。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-63a8dfbc-33b4-4656-89f1-0ffb6b37f349","tags":[]},{"id":"poem-a1c1e032847fb0b2f1eb6009","title":"凉思","author":"李商隐","dynasty":"唐","verses":["客去波平槛，蝉休露满枝。","永怀当此节，倚立自移时。","北斗兼春远，南陵寓使迟。","天涯占梦数，疑误有新知。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-15c6cbc9-753a-4f09-86bf-4fe2d8bb1fee","tags":["唐诗三百首","愁思","五言律诗"]},{"id":"poem-a1c653502a4aa457d02bbc33","title":"吕元直得书天台郭外治园林作退老堂求诗为赋两章  其一","author":"李纲","dynasty":"宋","verses":["猎得飞熊自渭滨，钓璜赐履定前身。","功髙浴日千山晓，力拒回天万国春。","暂辍岩廊调鼎手，来为林壑采芝人。","片帆云海无多地，叹息何缘厕末宾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-9824f270-4a49-4c0c-8e58-b4dbcf07ffb3","tags":[]},{"id":"poem-a1d14eb841cbb633c4f5aa7e","title":"奉和登会昌山应制","author":"孙逖","dynasty":"唐","verses":["岩磴列云旗，吾君访道时。","干行万物覩，日驭六龙迟。","望远回天顾，登高动睿词。","愿因山作寿，长保会昌期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ccff76d6-4bd6-4bb3-a4b0-59c2c766f9f7","tags":[]},{"id":"poem-a1d54bf50e957545cec4755e","title":"中秋风雨","author":"艾可叔","dynasty":"宋","verses":["一年佳节又虚逢，恼杀江湖白发翁。","滴梦欲残蕉叶雨，吹愁不断蓼花风。","阴晴明晦天无准，离合悲欢态不同。","聊买香醪作清赏，烛光闲对木犀红。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-83a07604-5326-49f0-ada7-26dcb3f7ac17","tags":[]},{"id":"poem-a1d82152b9662e3fd7c12253","title":"青哥儿","author":"杨景贤","dynasty":"元","verses":["呀！急煎煎无一个亲人相护，(刘做扯科)紧邦邦扯住了衣服，哎，你个粪土之墙不可木亏，又无甚钱物。","杀坏他身躯，倾陷了俺儿夫，强要他媳妇。","天意何如？人命何辜？哎！你个柳盗跖哥哥忒心毒，怎下得浪淘淘流将他去？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7945","tags":[]},{"id":"poem-a1da6e1f5af5e5c1aab7853a","title":"奉和圣制答张说南出雀鼠谷","author":"席豫","dynasty":"唐","verses":["鸣銮初幸代，旋盖欲横汾。","山尽千旗出，郊平五校分。","前林已暄景，后壑尚寒氛。","风送箫韶曲，花铺黼黻文。","盐梅推上宰，礼乐统中军。","献赋纡天札，飘飖飞白云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-5ded4090-008e-41f9-9279-ad581a1da886","tags":[]},{"id":"poem-a1e38b495239aefe14aefeff","title":"省题诗二十一首 上巳日曲江锡宴群臣","author":"王棨","dynasty":"唐","verses":["池散暮春景，君垂晞露恩。","妙音回舜乐，浓味降尧罇。","诏出倾兰省，筵开对杏园。","轻涟摇彩舰，芳草映华轩。","禊事辉朝曲，欢声彻帝门。","常陪观者列，低首望余暄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-cf693e4c-b030-4dcf-9db6-ccc146886660","tags":[]},{"id":"poem-a1e59f32d138afa5eae1c694","title":"致奠张柔直知郡龙图以诗四章哭之书置灵几以代祭文  其三","author":"李纲","dynasty":"宋","verses":["去岁如今会豫章，从容谈笑共衔觞。","岂期便作终天诀，尺素开时神内伤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-c7493646-700e-46bd-9fa8-473456af74c0","tags":[]},{"id":"poem-a1e6c54e434114909836a03d","title":"蝶恋花·贴鬓香云双绾绿","author":"李冠","dynasty":"宋","verses":["贴鬓香云双绾绿。","柳弱花娇，一点春心足。","不肯玉箫闲度曲。","恼人特把青蛾蹙。","静夜溪桥霜薄屋。","独影行歌，惊起双鸾宿。","愁破酒阑闺梦熟。","月斜窗外风敲竹。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-577","tags":[]},{"id":"poem-a1f9a1744ab432db0519457a","title":"千秋节宴","author":"明皇帝","dynasty":"唐","verses":["兰殿千秋节，称名万寿觞。","风传率土庆，日表继天祥。","玉宇开花蕚，宫县动会昌。","衣冠白鹭下，帟幕翠云长。","献遗成新俗，朝仪入旧章。","月衔花绶镜，露缀彩丝囊。","处处祠田祖，年年宴杖乡。","深思一德事，小获万人康。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-746656b4-b41f-4ef8-ad6d-02a30edc5fc5","tags":[]},{"id":"poem-a1fb5f739edab1afedfda897","title":"饮少","author":"赵崇嶓","dynasty":"宋","verses":["平生不善饮，饮少醉已极。","恨不如渊明，陶陶少虚日。","桑嵫无停景，寸晷足可惜。","今人与古人，展转不相识。","孰能制颓龄，扰扰竟何益。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-8b05557a-2bad-4295-bc1e-ee837f8a5ac6","tags":[]},{"id":"poem-a1fb5ffb0ce261c9a73a80da","title":"怡怡亭","author":"王景云","dynasty":"宋","verses":["老年常聚首，兄弟共怡怡。","并坐闲挥麈，交斟醒设巵。","双声频检韵，让道更敲棋。","自是天伦乐，嬉游似少时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-670d3b61-82ad-4c4d-b893-a8cab12bddb3","tags":[]},{"id":"poem-a200705676d72ba3a3de352b","title":"拜总持尼祖塔","author":"释居简","dynasty":"宋","verses":["平生自爱黄金膝，肯屈榛芜草棘深。","弗似灌溪闲上座，尼坛再展不同心。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-c5c68085-8d7b-484e-97b6-a4966cca5d66","tags":[]},{"id":"poem-a2045b661481c66e30cff99c","title":"麻婆子","author":"无名氏《张协状元》","dynasty":"元","verses":["二月春光好，秧针细细抽。","有时移步出田头，蝌蚪要无数水中游。","婆婆傍前捞一碗，急忙去买油。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2567","tags":[]},{"id":"poem-a20c37f6fe9f5e01f72261be","title":"送僧之湖外","author":"贯休","dynasty":"唐","verses":["去旨趣非常，春风尔莫狂。","惟擎一铁钵，旧亦讲金刚。","午饭孤烟里，宵禅大石旁。","羡师终不及，湘浪渌茫茫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-e484cc34-6bcd-463b-ae30-f8415b448932","tags":[]},{"id":"poem-a20c961d8d37979d421afbe3","title":"早春雪夜寄卢纶兼呈秘书元丞","author":"李端","dynasty":"唐","verses":["闻君随谢朓，春夜宿前川。","看竹云垂地，寻僧月满田。","熊寒方入树，鱼乐稍离船。","独夜羇愁客，惟知惜故年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-f99c8509-6d10-44bc-aa49-90dc515dd4ce","tags":[]},{"id":"poem-a20d74b744bbf62bfd1a6580","title":"唐虞门 唐尧","author":"周昙","dynasty":"唐","verses":["祆氛不起瑞烟轻，端拱垂衣日月明。","传事四方无外役，茅茨深处土堦平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-5acb2c09-00ec-442b-a39f-8e83ade6609a","tags":[]},{"id":"poem-a213dee9c28b37220636248c","title":"虞美人·芭蕉滴滴窗前雨","author":"洪适","dynasty":"宋","verses":["芭蕉滴滴窗前雨。","望断江南路。","乱云重叠几多山。","不似倦飞鸥鹭、便知还。","角声更听谯门弄。","夜夜思归梦。","鄱江楼下水含漪。","孤负钓滩烟艇、绿蓑衣。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-673","tags":[]},{"id":"poem-a21a83a3cb6e1d0487b993ee","title":"南乡子·归路近","author":"李珣","dynasty":"五代","verses":["归路近，扣舷歌，采真珠处水风多。","曲岸小桥山月过，烟深锁，豆蔻花垂千万朵。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-27","tags":[]},{"id":"poem-a21bbfee6991907f3523fe90","title":"春暮游小园","author":"王淇","dynasty":"宋","verses":["一从梅粉褪残妆，涂抹新红上海棠。","开到荼蘼花事了，丝丝夭棘出莓墙。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-春暮遊小園","tags":[]},{"id":"poem-a21e72233a43df00e5600cf5","title":"还","author":"佚名","dynasty":"先秦","verses":["子之还兮，遭我乎狃之间兮。并驱从两肩兮，揖我谓我儇兮。","子之茂兮，遭我乎狃之道兮。并驱从两牡兮，揖我谓我好兮。","子之昌兮，遭我乎狃之阳兮。并驱从两狼兮，揖我谓我臧兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-96","tags":[]},{"id":"poem-a21effa05c1566e3880a7a71","title":"和同年徐清溪韵","author":"柴元彪","dynasty":"宋","verses":["深隠柯云第几峰，一庭春草绿丛丛。","西风白发催人老，少日青袍与子同。","买犊只因耕荦确，拂龟何必问穷通。","蔗浆一洗相如渴，頼有新诗送远鸿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-c7dcad05-4a36-4fbc-93f0-541a256f3039","tags":[]},{"id":"poem-a22fb8370d9c1aa39c6f0dbf","title":"寄都官刘员外","author":"章八元","dynasty":"唐","verses":["旧宅平津邸，槐阴接汉宫。","鸣驺驰道上，寒日直庐中。","白雪歌偏丽，青云宦早通。","悠然一缝掖，千里限清风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-5c228217-7f18-441d-9c3b-539338458cf9","tags":[]},{"id":"poem-a23052b9659397ac6293dbbd","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["皇恩若念臣，我也不图，禄及吾身。","只愁恩不到双亲，空孤负，这孤坟。","(合前)(旦唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5273","tags":[]},{"id":"poem-a23fec8bcf974d10d20f2e6c","title":"下武","author":"佚名","dynasty":"先秦","verses":["下武维周，世有哲王。三后在天，王配于京。","王配于京，世德作求。永言配命，成王之孚。","成王之孚，下土之式。永言孝思，孝思维则。","媚兹一人，应侯顺德。永言孝思，昭哉嗣服。","昭兹来许，绳其祖武。于万斯年，受天之祜。","受天之祜，四方来贺。于万斯年，不遐有佐。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-242","tags":[]},{"id":"poem-a2493753721d8c8b24772c06","title":"故观文建安刘公挽诗四首  其四","author":"张栻","dynasty":"宋","verses":["曾是南荆地，他年竹马迎。","旌旗严骑士，弧矢盛民兵。","细考规摹旧，还知节制明。","思公如岘首，同我泪纵横。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-b65dd64b-7d19-40ed-849c-976b49dbcd95","tags":[]},{"id":"poem-a24d77c3a3863941348b97d3","title":"宿瓜州","author":"李绅","dynasty":"唐","verses":["烟昏水郭津亭晚，回望金陵若动摇。","冲浦回风翻宿浪，照沙低月歛残潮。","柳经寒露看萧索，人改衰容自寂寥。","官冷旧谙唯旅馆，岁阴轻薄是凉飙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-fc48d76d-a666-4b6b-9d4e-b54ce368198f","tags":[]},{"id":"poem-a25b7a2a5049a2e86f6deb99","title":"送张中丞入台从事","author":"李德裕","dynasty":"唐","verses":["驿骑朝天去，江城睠阙深。","夜珠先去握，芳桂乍辞阴。","泽国三千里，羁孤万感心。","自嗟文废久，此曲为卢谌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e6a6ad0f-3a83-4774-a906-ebb43f7ac5cf","tags":[]},{"id":"poem-a267136c9b80b306bc10788d","title":"豹子令","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(净)头带金盔八宝攒，八宝攒。","茜红袍带血腥膻，血腥膻。","雄威赳赳谁来犯？铁人见俺也心寒，也心寒。","(合)张弓跃马下山关，下山关。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8952","tags":[]},{"id":"poem-a26cec8fbeefafc83ba5470d","title":"书斋雪后","author":"赵嘏","dynasty":"唐","verses":["拥褐坐茅簷，春晴喜初日。","微风入桃径，爽气归缥帙。","频时苦风雪，就景理巾栉。","树暖高鸟来，窗闲曙云出。","乡遥路难越，道蹇时易失。","欲静又不能，东山负芝术。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-c20a6e02-376a-4edb-9891-99f728e54cae","tags":[]},{"id":"poem-a26de8fd4c5d25b18826c95b","title":"菩萨蛮·玉人又是匆匆去","author":"张先","dynasty":"宋","verses":["玉人又是匆匆去。","马蹄何处垂杨路。","残日倚楼时。","断魂郎未知。","阑干移倚遍。","薄幸教人怨。","明月却多情。","随人处处行。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-339","tags":[]},{"id":"poem-a27d68076f65ca9f005a4321","title":"同卫八题陆少府书斋","author":"高适","dynasty":"唐","verses":["知君薄州县，好静无冬春。","散帙至栖鸟，明灯留故人。","深房腊酒熟，高院梅花新。","若是周旋地，当令风义亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c1f1cc1d-4eff-438e-8aea-60cb69174965","tags":[]},{"id":"poem-a28047f83f833ca1677f3a91","title":"送韦判官赴闽中","author":"皇甫曾","dynasty":"唐","verses":["孤棹闽中客，双旌海上军。","路人从北少，海水向南分。","野鹤伤秋别，林猨忌夜闻。","汉家崇亚相，知子远邀勋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ffe2114c-a56d-4f43-bae4-49a13ec043e3","tags":[]},{"id":"poem-a28313e0b398e498338fcac4","title":"过谷口元赞善所居","author":"李端","dynasty":"唐","verses":["入谷访君来，秋泉已堪涉。","林间人独坐，月下山相接。","重露湿苍苔，明灯照黄叶。","故交一不见，素发何稠叠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-9fa9dfb2-4e4a-4c51-bd1f-bb28049777d9","tags":[]},{"id":"poem-a2863853cd46bce4eb03fff3","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［丑］畜生反面目，太心毒。","忘恩负义难容恕，真堪恶！且放怀，休疑虑。","他既贪图荣贵重婚娶，咱这里别选收花主。","［合前］。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8190","tags":[]},{"id":"poem-a287ec73448f6e39ec420788","title":"秋宵","author":"钱遹","dynasty":"宋","verses":["南邻灯火冷，三叹愁夜永。","北里歌未终，已惊初日红。","不知昼夜谁拘管，一等秋宵有长短。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-fe4fbca9-dec3-47bf-8084-1bc9288ae340","tags":[]},{"id":"poem-a29a39b81b26fdb7132902b9","title":"女冠子·四月十七","author":"韦庄","dynasty":"五代","verses":["四月十七，正是去年今日。","别君时，忍泪佯低面，含羞半敛眉。","不知魂已断，空有梦相随。","除却天边月，没人知。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-20","tags":[]},{"id":"poem-a29afa7e37b3b1b16725783a","title":"送宗无传赴闽帅杨伯子西禅之招","author":"释居简","dynasty":"宋","verses":["尚有诚斋老宁馨，来寻方外阿师兄。","滔滔入海如泾浊，冏冏于公独阮青。","旧忆薰莸分草木，新来一再扣柴荆。","不龟手是家传药，莫遣人言药不灵。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-3f824b71-3ca6-4956-8d7e-67af7118d69d","tags":[]},{"id":"poem-a29b2abfec86e138f388be6b","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(旦)男儿赎药。","把衣衫典当偿。","我不能够觑，我不能够觑得你身体康。","(生)我和你再。","我和你再得成双，怕死后一灵儿到你行。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3014","tags":[]},{"id":"poem-a29c2fc493cfec05b290017d","title":"小游仙诗九十八首 七十","author":"曹唐","dynasty":"唐","verses":["东皇长女没多年，从洗金芝到水边。","无事伴他棋一局，等闲输却卖花钱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-238ab7ce-a409-4223-8dc4-171cdf1caa9d","tags":[]},{"id":"poem-a2a757d99bd3b3c6500c268e","title":"冬日后作","author":"裴说","dynasty":"唐","verses":["寂寞掩荆扉，昏昏坐欲痴。","事无前定处，愁有并来时。","日影才添线，鬓根已半丝。","明庭正公道，应许苦心诗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-3515d0f8-7d6b-41c8-9f98-77366eb6b9ef","tags":[]},{"id":"poem-a2ab62022d6daa5a4d2b645d","title":"次韵余司理路监岳","author":"陈造","dynasty":"宋","verses":["入山日正烈，出山云忽浓。","身疑润空青，旋觉霏雨蒙。","归来坐良夜，淙泻如崩空。","县知焦卷地，转眼青芃芃。","似闻移晚秧，竭蹷不暇慵。","人计故新年，已判一倍丰。","此惠究所自，无乃西山龙。","泽物龙能之，叱使则天公。","我行与雨会，仅杀颜发红。","地上蝼蚁臣，渠敢贪天功。","两公壮藻思，表表千夫雄。","新诗猥见予，拜赐岂所蒙。","得意笔生春，状物斤成风。","生世有如愿，兼得宁易逢。","此诗自宫商，为君弦枯桐。","准拟鸡酒社，往和击壤翁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-c3ce8f23-b4c4-4ec5-aadf-63aa12464467","tags":[]},{"id":"poem-a2b40fc1d7fb84f4d67df25b","title":"采芑","author":"佚名","dynasty":"先秦","verses":["薄言采芑，于彼新田，呈此菑亩。方叔涖止，其车三千。师干之试，方叔率止。","乘其四骐，四骐翼翼。路车有奭，簟茀鱼服，钩膺鞗革。","薄言采芑，于彼新田，于此中乡。方叔涖止，其车三千。旗旐央央，方叔率止。","约軧错衡，八鸾玱玱。服其命服，朱芾斯皇，有玱葱珩。","𫛣彼飞隼，其飞戾天，亦集爰止。方叔涖止，其车三千。师干之试，方叔率止。","钲人伐鼓，陈师鞠旅。显允方叔，伐鼓渊渊，振旅阗阗。","蠢尔蛮荆，大邦为仇。方叔元老，克壮其犹。方叔率止，执讯获丑。戎车啴啴，啴啴焞焞，如霆如雷。显允方叔，征伐𤞤狁，蛮荆来威。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-177","tags":[]},{"id":"poem-a2b420f529aadb5f04ebd42c","title":"与月船周君话别  其二","author":"王同祖","dynasty":"宋","verses":["鸭炉烟冷夜窗寒，著尽冬衣尚怯单。","忽忆故人千里别，雁赍芳恨度扶栏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b94666cf-e793-4762-84e8-514d57f9f014","tags":[]},{"id":"poem-a2b882f4280b39fd5506403e","title":"夕发邠宁寄从弟","author":"马戴","dynasty":"唐","verses":["半酣走马别，别后锁边城。","日落月未上，鸟栖人独行。","方驰故国恋，复怆长年情。","入夜不能息，何当闲此生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b7bf1f91-98aa-4db7-8c64-2332247d7e3d","tags":[]},{"id":"poem-a2b976cf4f9bc26ab4877d31","title":"遣兴五首 五","author":"杜甫","dynasty":"唐","verses":["昔在洛阳时，亲友相追攀。","送客东郊道，遨游宿南山。","烟尘阻长河，树羽成臯间。","回首载酒地，岂无一日还。","丈夫贵壮健，惨戚非朱颜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-13f2246e-b05e-44aa-b907-b642cc77defc","tags":[]},{"id":"poem-a2bb98760730d1d816621cea","title":"霓裳羽衣歌","author":"鲍溶","dynasty":"唐","verses":["玉烟生窗午轻凝，晨华左耀鲜相凌。","人言天孙机上亲手迹，有时怨别无所惜。","遂令武帝厌云韶，金针天丝缀飘飘。","五声写出心中见，拊石喧金栢梁殿。","此衣春日赐何人，秦女腰肢轻若燕。","香风间旋众彩随，联联珍珠贯长丝。","眼前意是三清客，星宿离离遶身白。","鸾凤有声不见身，出宫入征随伶人。","神仙如月只可望，瑶华池头几惆怅。","乔山一闭曲未终，鼎湖秋惊白头浪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-7f92abb6-a723-45a1-baf0-dc5c4078a0ef","tags":[]},{"id":"poem-a2bcb6ff12b5d6d358c2b594","title":"驷驖","author":"佚名","dynasty":"先秦","verses":["驷驖孔阜，六辔在手。公之媚子，从公于狩。","奉时辰牡，辰牡孔硕。公曰左之，舍拔则获。","游于北园，四马既闲。𬨎车鸾镳，载猃歇骄。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-126","tags":[]},{"id":"poem-a2c22d4456800f0818f0f085","title":"赠送行六子  其一","author":"陈造","dynasty":"宋","verses":["北风猎猎吹行舟，客子坎止今乘流。","汀洲立鹭仍飞鸥，定应笑我当退休。","一贫所驱不自由，表表六子古与俦。","知我此意不见羞，送行两舍未转头。","我生甚愧羊荆州，郭吉校君谁劣优。","天气冰井风力遒，召棠芜城甘滞留。","推挽共作平山游，倚栏逸兴浩莫收。","剧谭落屑酒溜油，不许旅寓生羁愁。","饱阅世态谙枵浮，高情如君未易求。","嗟予老矣胡为酬，相与金玉论轲丘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-f2863de9-0e00-44b6-ba3e-ff81a44cd9a2","tags":[]},{"id":"poem-a2d2ef07cb0cb8b8e7d57bcb","title":"送蜀客","author":"张籍","dynasty":"唐","verses":["蜀客南行祭碧鸡，木棉花发锦江西。","山桥日晚行人少，时见猩猩树上啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-b84243ce-8627-4860-9065-f36af42441e8","tags":[]},{"id":"poem-a2d41b237b88f8307d431c4c","title":"减字木兰花·笔端红翠","author":"赵鼎","dynasty":"宋","verses":["笔端红翠。","造化工夫春有意。","云梦涵胸。","好去蓬山十二重。","天街追骑。","催唤谪仙泥样醉。","电扫云空。","百斛明珠咳唾中。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-946","tags":[]},{"id":"poem-a3060c2d4696bdc92e8f0a9a","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(旦)秀才，你儒业祖传袭，文章幼攻习。","我低低问，暗暗猜，心疑忌，叔伯远房姑舅的？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2968","tags":[]},{"id":"poem-a31f862ba446b69663072868","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(生)从来结义深，他还沦旨我怎生禁？休误人言难信。","夫妻有话且三分，未可全抛一片心。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1908","tags":[]},{"id":"poem-a321b40a026a1a7d51f50b1c","title":"点绛唇","author":"施惠《幽闺记》","dynasty":"元","verses":["(净扮番将上)势压中华，仁将夷化，威风大。","一曲琵琶，醉后驱鹰马。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2855","tags":[]},{"id":"poem-a325b2317a7fc4b1a0778b0c","title":"端州江亭得家书二首 二","author":"李绅","dynasty":"唐","verses":["长安别日春风早，岭外今来白露秋。","莫道淮南悲木叶，不闻摇落更堪愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ad36b445-fdba-4b15-b591-d254c1242ff0","tags":[]},{"id":"poem-a325e9563dda2a30a45ec9bd","title":"平时兄弟间十三章章四句送定叟弟之官桂林  其四","author":"张栻","dynasty":"宋","verses":["呜呼忠献公，典则垂后裔。","遗言故在耳，夕惕当自厉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-db3adf15-162e-4e51-8846-0df0a4c83956","tags":[]},{"id":"poem-a33332855ff56bba3cdec361","title":"古意代友人投所知","author":"贯休","dynasty":"唐","verses":["青松虽有花，有花不如无。","贫井泉虽清，且无金辘轳。","客从远方来，遗我古铜镜。","挂之玉堂上，如对轩辕圣。","天龙睡坤腹，土蚀金鬣绿。","因知燕赵佳人颜似玉，不得此镜终不。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-9c937474-d08e-47e8-bf3e-309d00eed91f","tags":[]},{"id":"poem-a33579ac4b53a6b723d2f8e4","title":"览陈拾遗文集（按题下原署名曰「东川观察判官长沙刘蜕」。）","author":"刘蜕","dynasty":"唐","verses":["郪中好事人，家藏君十轴。","余来多暇日，借得昼夜读。","意气高于头，冰霜冷人腹。","就中《大雅》篇，日日吟不足。","生遇明皇帝，君臣竟不识。","沉湮死下位，我辈更莫卜。","射洪客来说，露碑今已踣。","剜刓存灭半，势欲入沟渎。","寓书托宰君，请为试摩挃。","树之四达地，覆碑高作屋。","愤君死后名，再依泥沙辱。","世路重富贵，婉娩好眉目。","文学如君辈，安得足衣食。","不死横路渠，为幸已多福。","我有平生心，推残不局促。","揖君盛年名，万钟何足禄。","量长复校短，凫胫不愿续。","悲君泪垂颐，云山空蜀国。","（见《永乐大典》卷三一三四「九真」「陈」字「阳子昂」条引《潼川志》〖五函四十四册〗。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-68d6bce0-c0bc-40b1-999b-a25870e2d380","tags":[]},{"id":"poem-a33b04d68fec6337878197e9","title":"送潍州詹倅五首  其三","author":"綦崇礼","dynasty":"宋","verses":["东风催去旆，南浦伤离情。","攀辕何纷纷，晓日来倾城。","中有韦布士，雪涕挥纵横。","欲识何为者，为言门下生。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-bb5399cb-9eb7-4562-baf3-da9703b1ea42","tags":[]},{"id":"poem-a353afc91033d5f457f6ab7b","title":"禁中春松","author":"周存","dynasty":"唐","verses":["几岁含贞节，青青紫禁中。","日华留偃盖，雉尾转春风。","不为繁霜改，那将众木同。","千条攒翠色，百尺澹晴空。","影密金茎近，花明凤沼通。","安知幽涧侧，独与散樗丛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-0de77f00-258c-4c9b-b8a2-6f79bd0c3c66","tags":[]},{"id":"poem-a355457c76c2eb7065f83a7c","title":"汾上惊秋","author":"苏颋","dynasty":"唐","verses":["北风吹白云，万里渡河汾。","心绪逢摇落，秋声不可闻。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-汾上驚秋","tags":[]},{"id":"poem-a35e8a8241f785383f74fcc6","title":"玉交枝","author":"无名氏《宦门子弟错立身》","dynasty":"元","verses":["只因痴迷，与王金榜同谐比翼。","谁知被我爹捉住，拆散了鸳侣。","情人去也不见踪，我如今在此无依倚。","免不得寻个死处，免不得寻个死处。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-314","tags":[]},{"id":"poem-a3611ad5f3146c873bfd340c","title":"汤泉应制·六龙初驻浴蓝天","author":"纳兰性德","dynasty":"清","verses":["六龙初驻浴蓝天，碧瓦朱旗共一川。","润逼仙桃红自舞，醉酣人柳绿犹眠。","吹成暖律回燕谷，散作薰风入舜弦。","最是垂衣深圣德，不须词笔颂甘泉。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-234","tags":[]},{"id":"poem-a3634f648982051c246bc9e4","title":"下京口埭夜行","author":"孙逖","dynasty":"唐","verses":["孤帆度绿氛，寒浦落红曛。","江树朝来出，吴歌夜渐闻。","南溟接潮水，北斗近乡云。","行役从兹去，归情入鴈群。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-46354a02-69ce-43b9-afd7-12a7b49ae671","tags":[]},{"id":"poem-a3683c48c26eca552da5e42f","title":"雄县观鱼","author":"纳兰性德","dynasty":"清","verses":["渔师临广泽，侍从俯清澜。","瑞入王舟好，仁知圣网宽。","拨鳞飞白雪，行鲙缕金盘。","在藻同周宴，时容万姓看。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-238","tags":[]},{"id":"poem-a36f521543751dd716265fca","title":"一丛花令・一丛花·伤高怀远几时穷","author":"张先","dynasty":"宋","verses":["伤高怀远几时穷。","无物似情浓。","离愁正引千丝乱，更东陌、飞絮蒙蒙。","嘶骑渐遥，征尘不断，何处认郎踪。","双鸳池沼水溶溶。","南北小桡通。","梯横画阁黄昏后，又还是、斜月帘栊。","沈恨细思，不如桃杏，犹解嫁东风。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-283","tags":["宋词三百首"]},{"id":"poem-a36f8a3b954dfc814b95a826","title":"弼公院问病","author":"刘言史","dynasty":"唐","verses":["一头细发两分丝，卧见芭蕉白露滋。","欲令居士身无病，直待众生苦尽时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-62398c45-64ca-45a1-af5c-f788c479f1f8","tags":[]},{"id":"poem-a3709425c3ef12dd6e6eb2e8","title":"山居遣兴四首  其三","author":"李纲","dynasty":"宋","verses":["秋杪幽居分外清，傍簷鸟雀自和鸣。","过时黄菊浑无赖，入眼青山独有情。","酒后晕红潮玉颊，吟余儿杖殷金声。","前村野老能棋战，时与呼来对一枰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-5d85f826-3e19-4af0-92e7-2410ec881064","tags":[]},{"id":"poem-a370af265828344096a8f1fc","title":"美人梳头","author":"张碧","dynasty":"唐","verses":["玉堂花院小枝红，绿窗一片春光晓。","玉容惊觉浓睡醒，圆蟾挂出妆台表。","金盘解下丛鬟碎，三尺巫云绾朝翠。","皓指高低寸黛愁，水精梳滑参差坠。","须臾拢掠蝉鬓生，玉钗冷透冬冰明。","芙蓉拆向新开脸，秋泉慢转眸波横。","鹦鹉偷来话心曲，屏风半倚遥山绿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e66e7b43-a267-43d2-a201-49c17bcddcf9","tags":[]},{"id":"poem-a374534ca39799c50cd13976","title":"摘得新·摘得新","author":"皇甫松","dynasty":"唐","verses":["摘得新，枝枝叶叶春。","管弦兼美酒，最关人。","平生都得几十度，展香茵。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-23","tags":[]},{"id":"poem-a376b937676e7ced79e038be","title":"用前送行韵寄赵编修可斋","author":"释居简","dynasty":"宋","verses":["烁石与金流，怀人眺晚楼。","忽闻提健笔，喜似得神州。","稻粒不多日，窗疏相次秋。","只分千里月，木李不中投。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-26f11116-72d0-4e1a-b1f3-7613d780e6e7","tags":[]},{"id":"poem-a3869034e55390dd235a245c","title":"闻沈宏父讣","author":"释居简","dynasty":"宋","verses":["云裘未换貂，鬓已几茎雕。","璞美宜穹售，楼成或下招。","生无金润屋，死有玉蕃苗。","欲酹余不土，天浆弗满瓢。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-a9749fd8-c90d-475f-9edd-e9ac913924d0","tags":[]},{"id":"poem-a3886a5b2393b430afd2f2b4","title":"黄钟尾","author":"萧德祥《小孙屠》","dynasty":"元","verses":["如今未遭际汉风雷信，有一日得到家乡桃李春。","打旋回来分，参拜了母亲，答谢了众神，便受了奔波正的本。","(下)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8597","tags":[]},{"id":"poem-a38eaf69ef516a9aa6f7093d","title":"寄人 一","author":"张泌","dynasty":"唐","verses":["别梦依依到谢家，小廊回合曲阑斜。","多情只有春庭月，犹为离人照落花。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-afc2e6d6-e67f-4513-a6ab-82841d2f97cc","tags":["唐诗三百首","思念","七言绝句","月亮","爱情"]},{"id":"poem-a390ed55add7299db6bf11d7","title":"凤栖梧・蝶恋花·狂滥生涯今几许","author":"蔡楠","dynasty":"宋","verses":["狂滥生涯今几许。","敕赐湖天，万顷烟波主。","约我小舟同老去。","要前一叶风掀舞。","邂逅同寻溪上路。","淡墨题诗，正在云深处。","别后作书频寄语。","无忘林下萧萧雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-851","tags":[]},{"id":"poem-a3990aa67d25bad4aec07440","title":"送窦拾遗赴朝因寄中书十七弟","author":"李嘉祐","dynasty":"唐","verses":["自叹未沾黄纸诏，那堪远送赤墀人。","老为侨客偏相恋，素是诗家倍益亲。","妻儿共载无羁思，鸳鹭同行不负身。","凭尔将书通令弟，唯论华发愧头巾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2ce226b7-ea64-4eff-8070-de1fefab65b3","tags":[]},{"id":"poem-a39e86a378fc192150c97174","title":"春日覊情","author":"佚名","dynasty":"唐","verses":["乡山临海岸，别业近天堄。","地接龙塠北，川连雁塞西。","童年方剃削，弱冠导群迷。","儒释双披（原作「柀」）玩，声名独见跻。","须缘随垦请，今乃恨暌携。","寂寂空愁坐，迟迟落日低。","触槐常有志，折槛为无蹊。","薄暮荒城外，依稀闻远鸡。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-25c2efd7-faa5-4b26-963b-8b6eac1fcc62","tags":[]},{"id":"poem-a3acaf32523aa928726e53e2","title":"贫女观音","author":"释居简","dynasty":"宋","verses":["雪藕铢衣不自珍，人间丝枲谩纷纭。","何如小白花山上，别剪彤霞与白云。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-d72dac63-1974-4dcd-bcaa-ebc89724eabd","tags":[]},{"id":"poem-a3b149635fb161fdbb78eb65","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(老旦)衰老年，只愁烟瘴为吾患。","幸家门吉庆，子母平安。","今日里子擢高官，饮别酒应难留恋。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8285","tags":[]},{"id":"poem-a3b3cb3e0d8cf09dae51391a","title":"赋戚夫人楚舞歌","author":"李昂","dynasty":"唐","verses":["定陶城中是妾家，妾年二八颜如花。","闺中歌舞未终曲，天下死人如乱麻。","汉王此地因征战，未出帘栊人已荐。","风花菡萏落辕门，云雨裴回入行殿。","日夕悠悠非旧乡，飘飘处处逐君王。","闺门向里通归梦，银烛迎来在战场。","相从顾恩不顾己，何异浮萍寄深水。","逐战曾迷只轮下，随君几陷重围里。","此时平楚复平齐，咸阳宫阙到关西。","珠帘夕殿闻钟磬，白日秋天忆鼓鼙。","君王纵恣翻成误，吕后由来有深妬。","不奈君王容鬓衰，相存相顾能几时。","黄泉白骨不可报，雀钗翠羽从此辞。","君楚歌兮妾楚舞，脉脉相看两心苦。","曲未终兮袂更扬，君流涕兮妾断肠。","已见储君归惠帝，徒留爱子付周昌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-4813666e-41fc-406f-9d4d-8029b21b0543","tags":[]},{"id":"poem-a3c7544b7f2e7c807180857b","title":"浆水令","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["你当初不听我们，到如今被他负恩。","［外］世间谁是预知人，何须斗口与我相争？［丑］都忍耐，听解纷，家必自毁令人晒。","［合］寻思起教人气忿。","谁知道，谁知道恁般不仁。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8194","tags":[]},{"id":"poem-a3c903d5ec8e461270dff42c","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［净］家私虽富足，心性忒愚鲁，向书斋懒读者也之乎。","无才学休想学干禄，有才的便能身挂绿。","［合前］。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8025","tags":[]},{"id":"poem-a3e5a51f12af0d62e526ea2d","title":"雨无正","author":"佚名","dynasty":"先秦","verses":["浩浩昊天，不骏其德。降丧饥馑，斩伐四国。旻天疾威，弗虑弗图。舍彼有罪，既伏其辜。若此无罪，沦胥以铺。","周宗既灭，靡所止戾。正大夫离居，莫知我勚。三事大夫，莫肯夙夜。邦君诸侯，莫肯朝夕。庶曰式臧，覆出为恶。","如何昊天，辟言不信。如彼行迈，则靡所臻。凡百君子，各敬尔身。胡不相畏，不畏于天？","戎成不退，饥成不遂。曾我暬御，惨惨日瘁。凡百君子，莫肯用讯。听言则答，谮言则退。","哀哉不能言，匪舌是出，维躬是瘁。哿矣能言，巧言如流，俾躬处休！","维曰予仕，孔棘且殆。云不何使，得罪于天子；亦云可使，怨及朋友。","谓尔迁于王都。曰予未有室家。鼠思泣血，无言不疾。昔尔出居，谁从作尔室？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-193","tags":[]},{"id":"poem-a3e7161c811895edbcb556ff","title":"登总持阁","author":"岑参","dynasty":"唐","verses":["高阁逼诸天，登临近日边。","晴开万井树，愁看五陵烟。","槛外低秦岭，窗中小渭川。","早知清净理，常愿奉金仙。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-登總持閣","tags":[]},{"id":"poem-a3efc14d57f869702aea95b1","title":"鹧鸪天·日日青楼醉梦中","author":"张孝祥","dynasty":"宋","verses":["日日青楼醉梦中。","不知楼外已春浓。","杏花未遇疏疏雨，杨柳初摇短短风。","扶画鹢，跃花骢。","涌金门外小桥东。","行行又入笙歌里，人在珠帘第几重。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-389","tags":[]},{"id":"poem-a3f0ef351c7be76f5e464138","title":"道元上人累示禅偈诗笔并诸贤赓唱见索鄙作因成短句奉酬","author":"苏颂","dynasty":"宋","verses":["释子南宗秀，囊文数见过。","灯分壁观后，诗学宝书多。","摘句心游刃，谈空辩注河。","儒林盛推挹，风势张云柯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-38ebbfa0-044c-4cf9-9006-75d7bf93009f","tags":[]},{"id":"poem-a3f10f7ba079ffd9abff605a","title":"首夏花萼楼观群臣宴宁王山亭回楼下又申之以赏乐赋诗","author":"明皇帝","dynasty":"唐","verses":["今年通闰月，入夏展春辉。","楼下风光晚，城隅宴赏归。","九歌扬政要，六舞散朝衣。","天喜时相合，人和事不违。","礼中推意厚，乐处感心微。","别赏阳台乐，前旬暮雨飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-9a42f0ea-06a9-4bb4-a71a-f4ba0485cb5f","tags":[]},{"id":"poem-a3fbde67539916b7f4c2f059","title":"九叹·忧苦","author":"刘向","dynasty":"汉","verses":["悲余心之悁悁兮，哀故邦之逢殃。","辞九年而不复兮，独茕茕而南行。","思余俗之流风兮，心纷错而不受。","遵野莽以呼风兮，步从容于山廋。","巡陆夷之曲衍兮，幽空虚以寂寞。","倚石岩以流涕兮，忧憔悴而无乐。","登巑岏以长企兮，望南郢而闚之。","山修远其辽辽兮，涂漫漫其无时。","听玄鹤之晨鸣兮，于高冈之峨峨。","独愤积而哀娱兮，翔江洲而安歌。","三鸟飞以自南兮，览其志而欲北。","原寄言于三鸟兮，去飘疾而不可得。","欲迁志而改操兮，心纷结其未离。","外彷徨而游览兮，内恻隐而含哀。","聊须臾以时忘兮，心渐渐其烦错。","原假簧以舒忧兮，志纡郁其难释。","叹《离骚》以扬意兮，犹未殚于《九章》。","长嘘吸以于悒兮，涕横集而成行。","伤明珠之赴泥兮，鱼眼玑之坚藏。","同驽骡与乘驵兮，杂斑駮与阘茸。","葛藟蔂于桂树兮，鸱鸮集于木兰。","偓促谈于廊庙兮，律魁放乎山间。","恶虞氏之箫《韶》兮，好遗风之《激楚》。","潜周鼎于江淮兮，爨土鬵于中宇。","且人心之持旧兮，而不可保长。","邅彼南道兮，征夫宵行。","思念郢路兮，还顾睠睠。","涕流交集兮，泣下涟涟。","叹曰：登山长望中心悲兮，菀彼青青泣如颓兮，留思北顾涕渐渐兮，折锐摧矜凝泛滥兮，念我茕茕魂谁求兮，仆夫慌悴散若流兮。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-52","tags":[]},{"id":"poem-a3fe3a42fef5f8b651e0be3d","title":"武陵春·今岁重阳经闰早","author":"曹勋","dynasty":"宋","verses":["今岁重阳经闰早，金蕊粲繁枝。","玉殿珠楼步辇随。","高兴在东篱。","且泛金英同潋滟，休与傲霜期。","只恐秋香一夜衰。","须插满头归。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-167","tags":[]},{"id":"poem-a3ff48de4cd51a6105f752f0","title":"大蜀皇帝寿春节进尧铭舜颂二首 舜颂","author":"贯休","dynasty":"唐","verses":["高高历山，有黍有粟。","皇皇大舜，合尧玄德。","五典克从，四门伊穆。","大道将行，天下为公。","临下有赫，选贤用能。","吾皇则之，无斁无逸。","绥厥品汇，光光得一。","千辐临顶，十在随跸。","大哉大同，为光为龙。","吾皇则之，圣谋隆隆。","纳隍孜孜，攷攷切切。","六宗是禋，五瑞斯列。","排麟环凤，披香立雪。","四夷纳賮，九围有截。","昔救世师，降生竺乾。","寿春亦然，万年万年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-bc3f76e0-612a-4477-b75c-48fc94778f2d","tags":[]},{"id":"poem-a407a7e70be471bdf08a3ede","title":"送苏修游上饶","author":"崔峒","dynasty":"唐","verses":["爱尔无羁束，云山恣意过。","一身随远岫，孤棹任轻波。","世事关情少，渔家寄宿多。","芦花浅淡处，江月奈人何。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-58703b0a-258d-4de7-bb1e-c6587cb8bfea","tags":[]},{"id":"poem-a4095930fda983eebfc2f116","title":"生查子·月姊倚秋风","author":"向子𬤇","dynasty":"宋","verses":["月姊倚秋风，香度青林杪。","吹堕酒杯中，笑靥撩人小。","芗林万事休，独此情未了。","醉里又题诗，不觉花前老。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-136","tags":[]},{"id":"poem-a40b7f30d997e2929235c1f0","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 三十八","author":"易静","dynasty":"唐","verses":["欲捕捉，玄武定三传。","相克三传皆捉得，相生不克是无缘，好记不虚言。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-b55b78f4-2cdd-4efd-b3a2-bc56f6c8ad37","tags":[]},{"id":"poem-a40fd663264ead2d7e7ac59c","title":"答李儋","author":"韦应物","dynasty":"唐","verses":["去年花里逢君别，今日花开又一年。","世事茫茫难自料，春愁黯黯独成眠。","身多疾病思田里，邑有流亡愧俸钱。","闻道欲来相问讯，西楼望月几回圆。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-答李儋","tags":[]},{"id":"poem-a4111e50023f4711dd445452","title":"秋过钱塘江","author":"贯休","dynasty":"唐","verses":["巨浸东隅极，山吞大野平。","因知吴相恨，不尽海涛声。","黑气腾蛟窟，秋云入战城。","游人千万里，过此白髭生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-fae002b8-9045-43d3-be91-69102ee2f677","tags":["钱塘江"]},{"id":"poem-a412f2ffc2c96eb9684cf68d","title":"谪后再书一绝","author":"卢肇","dynasty":"唐","verses":["崆峒道士悮烧丹，赤鼠黄牙几许难。","坠堕阎浮南斗下，不知何事犯星官。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-8ca8e155-a2e7-466b-b002-509820884ebc","tags":[]},{"id":"poem-a413fe54a0d238f3068b5256","title":"忽不贫喜卢仝书船归洛","author":"孟郊","dynasty":"唐","verses":["贫孟忽不贫，请问孟何如。","卢仝归洛船，崔嵬但载书。","江潮清翻翻，淮潮碧徐徐。","夜信为朝信，朝信良卷舒。","江淮君子水，相送仁有余。","我去官色衫，肩经入君庐。","喃喃肩经郎，言语倾琪琚。","琪琚铿好词，鸟鹊跃庭除。","书船平安归，喜报乡里闾。","我愿拾遗柴，巢经于空虚。","下免尘土侵，上为云霞居。","日月更相锁，道义分明储。","不愿空岧峣，但愿实工夫。","实空二理微，分别相起予。","经书荒芜多，为君勉勉锄。","勉勉不敢专，传之方在诸。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-dd77b4e7-0f9f-478f-a2cc-7da99c6b9827","tags":[]},{"id":"poem-a416b12bf51e4918ce1d8980","title":"哭徐删定德襄  其一","author":"林光朝","dynasty":"宋","verses":["修文巷里莫春前，欲上旗亭问客船。","忽有短牋无寄处，渔梁却在泪痕边。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-8d51975d-8c84-4061-98f9-868b6cd9bc5e","tags":[]},{"id":"poem-a4171e431d1512c574533257","title":"浪涛沙・浪淘沙·昼阴重","author":"周邦彦","dynasty":"宋","verses":["昼阴重，霜凋岸草，雾隐城堞。","南陌脂车待发。","东门帐饮乍阕。","正拂面垂杨堪缆结。","掩红泪、玉手亲折。","念汉浦离鸿去何许，经时信音绝。","情切。","望中地远天阔。","向露冷风清，无人处、耿耿寒漏咽。","嗟万事难忘，唯是轻别。","翠尊未竭。","凭断云留取，西楼残月。","罗带光销纹衾叠。","连环解、旧香顿歇。","怨歌永、琼壶敲尽缺。","恨春去、不与人期，弄夜色，空馀满地梨花雪。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-229","tags":["宋词三百首"]},{"id":"poem-a418e574842869ccba7e384f","title":"中书相公谿亭闲宴依韵","author":"徐铉","dynasty":"宋","verses":["雨霁秋光晚，亭空野兴回。","沙鸥掠岸去，谿水上阶来。","客傲风欺帻，筵香菊在杯。","东山长许醉，何事忆天台。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-5fcbc56a-c62a-4228-a802-c0070c0167fb","tags":[]},{"id":"poem-a41b5d05880b3a2dc0ad13b6","title":"上归州刺史代通状二首 二","author":"怀濬","dynasty":"唐","verses":["家在闽山东复东，其中岁岁有花红。","而今不在花红处，花在旧时红处红。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-92c3cd1a-2451-49f5-8361-0d2be7c68086","tags":[]},{"id":"poem-a41b91305f0ffef92a36485e","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(丑)钧命敢迟延。","这姻缘非偶然，匪媒弗克成姻眷，调和两边并无一言。","人间第一要行方便，今日递丝鞭，仙郎肯受，多赠贯头钱。","(外)媒婆，还有一件，恐二位状元不知小姐媸妍，将这真容与他看去。","(丑)理会得。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3089","tags":[]},{"id":"poem-a4236b934ac14f59d51e9240","title":"春夜别友人","author":"陈子昂","dynasty":"唐","verses":["银烛吐青烟，金尊对绮筵。","离堂思琴瑟，别路绕山川。","明月悬高树，长河没晓天。","悠悠洛阳道，此会在何年。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-春夜別友人","tags":[]},{"id":"poem-a42bd425be47c41df98a1dc3","title":"西溪子·昨日西溪游赏","author":"毛文锡","dynasty":"五代","verses":["昨日西溪游赏，芳树奇花千样，锁春光。","金樽满，听弦管，娇妓舞衫香暖。","不觉到斜晖，马驮归。","中兴乐。","豆蔻花繁烟艳深，丁香软结同心。","翠鬟女，相与共淘金。","红蕉叶里猩猩语，鸳鸯浦，镜中鸾舞。","丝雨隔，荔枝阴。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-9","tags":[]},{"id":"poem-a42c0ae780fde8fe54d75081","title":"送皎然上人归山","author":"李端","dynasty":"唐","verses":["适来世上岂缘名，适去人间岂为情。","古寺山中几日到，高松月下一僧行。","云阴鸟道苔方合，雪映龙潭水更清。","法主欲归须有说，门人流泪厌浮生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-9b9e4720-2ced-46a8-8cd2-be4575f67658","tags":[]},{"id":"poem-a42c83c2934147a5d16bd7c7","title":"遐方怨·凭绣槛","author":"温庭筠","dynasty":"唐","verses":["凭绣槛，解罗帷。","未得君书，肠断，潇湘春雁飞。","不知征马几时归，海棠花谢也，雨霏霏。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-2","tags":[]},{"id":"poem-a43c02f603908da5141d2a9f","title":"偈","author":"释闻一","dynasty":"宋","verses":["拈花微笑虚劳力，立雪齐腰枉用功。","争似老卢无用处，却传衣钵振真风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-669aa86c-c93e-420c-818b-1283a37bb21e","tags":[]},{"id":"poem-a43d0203a4a12a77d030745b","title":"送鲍中丞赴太原","author":"卢纶","dynasty":"唐","verses":["分路引鸣驺，喧喧似陇头。","暂移西掖望，全解北门忧。","专幕临都护，分曹制督邮。","积冰营不下，盛雪猎方休。","白草连胡帐，黄云拥戍楼。","今朝送旌斾，一减鲁儒羞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-90bab4dd-df1b-4079-9c1d-16b826f242ab","tags":[]},{"id":"poem-a453066b786b7f5f3ab8be1f","title":"寄昭应王中丞","author":"张籍","dynasty":"唐","verses":["借得街西宅，开门渭水头。","长贫唯要健，渐老不禁愁。","独凭藤书案，空悬竹酒钩。","春风石瓮寺，作意共君游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-f62bdde6-4814-4e8b-a607-f5a2a9881d0d","tags":[]},{"id":"poem-a45771a63b6a8026c09c18b7","title":"风流子·茅舍槿篱溪曲","author":"孙光宪","dynasty":"五代","verses":["茅舍槿篱溪曲，鸡犬自南自北。","菰叶长，水葓开，门外春波涨绿。","听织，声促，轧轧鸣梭穿屋。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-25","tags":[]},{"id":"poem-a45f87d5c2e417024b71df2c","title":"自河南经乱关内阻饥兄弟离散各在一处因望月有感聊书所怀寄上浮梁大兄於潜七兄乌江十五兄兼示符离及下邽弟妹","author":"白居易","dynasty":"唐","verses":["时难年饥世业空，弟兄羇旅各西东。","田园寥落干戈后，骨肉流离道路中。","吊影分为千里鴈，辞根散作九秋蓬。","共看明月应垂泪，一夜乡心五处同。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a2aed629-465d-412c-a68d-780068488725","tags":["唐诗三百首"]},{"id":"poem-a461148a7706c0fa380369be","title":"题果斋集后","author":"王柏","dynasty":"宋","verses":["童髽及侍果斋贤，白璧沈埋二十年。","师道倦为莲幕客，诗魂蜚伴雪堂僊。","同游诸老无人在，所幸斯文有子传。","读到徐卿珠玉句，抚膺三叹愧遗编。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-dc799227-cd5c-4c73-931f-349ff31e0785","tags":[]},{"id":"poem-a4656aea843c13134a12772d","title":"扬州后土祠琼花","author":"鲜于侁","dynasty":"宋","verses":["百蘤天下多，琼花天上稀。","结根托灵祠，地著不可移。","八蓓冠群芳，一株攒万枝。","孤生淮海上，晚秀清和时。","携赏偶佳辰，暗香盈酒卮。","倾都走庙下，爱玩如调饥。","皦月正交光，薰风正离披。","惟应神仙人，收拾繁英归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-4d8e1372-31ff-4dd9-984e-0ebbfaf7abd0","tags":[]},{"id":"poem-a465b205a832afc9d5dff3e1","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(末)东人富室豪门，论结交须谨慎。","他人怎比得亲骨肉？久久见假和真。","寻思及早回头省，莫把亲人如陌路人。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1695","tags":[]},{"id":"poem-a4734ae15354418a122df8d8","title":"庚戌正月一日游都峤山留五绝句栖真观中  其四","author":"李纲","dynasty":"宋","verses":["叠嶪髙岩耸八峰，云间紫翠郁相重。","故应洞穴通勾漏，更爱林峦接大容。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-2e5e56fc-0c4c-49d3-ac7a-16b5c598c75b","tags":[]},{"id":"poem-a474b5ffac565d8c779f45b4","title":"长发","author":"佚名","dynasty":"先秦","verses":["浚哲维商，长发其祥。洪水芒芒，禹敷下土方。外大国是疆，幅陨既长。有娀方将，帝立子生商。","玄王桓拨，受小国是达，受大国是达。率履不越，遂视既发。相士烈烈。海外有截。","帝命不违，至于汤齐。汤降不迟，圣敬日跻。昭假迟迟，上帝是祗，帝命式于九围。","受小球大球，为下国缀旒，何天之休。不竞不絿，不刚不柔。敷政优优。百禄是遒。","受小共大共，为下国骏厖。何天之龙，敷奏其勇。不震不动，不戁不竦，百禄是总。","武王载旆，有虔秉钺。如火烈烈，则莫我敢曷。苞有三蘖，莫遂莫达。九有有截，韦顾既伐，昆吾夏桀。","昔在中叶，有震且业。允也天子，降予卿士。实维阿衡，实左右商王。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-303","tags":[]},{"id":"poem-a4840bfe4d1f354f55d61505","title":"小重山·鹤舞青青雪里松","author":"毛滂","dynasty":"宋","verses":["鹤舞青青雪里松。","冰开龟在藻，绿蒙茸。","一成不记蕊珠宫。","蟠桃熟，应待几东风。","玉酒紫金锺。","非烟罗幕暖，宝熏秾。","赠君春色腊寒中。","君留取，长伴脸边红。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-751","tags":[]},{"id":"poem-a48827778338f9900c441416","title":"虞美人·深闺春色劳思想","author":"顾敻","dynasty":"五代","verses":["深闺春色劳思想，恨共春芜长。","黄鹂娇啭泥芳妍，杏枝如画倚轻烟，琐窗前。","凭栏愁立双蛾细，柳影斜摇砌。","玉郎还是不还家，教人魂梦逐杨花，绕天涯。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-37","tags":[]},{"id":"poem-a4997a98b543da279c56f648","title":"巫山高","author":"李端","dynasty":"唐","verses":["巫山十二峰，皆在碧虚中。","回合云藏月，霏微雨带风。","猿声寒过涧，树色暮连空。","愁向高唐望，清秋见楚宫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-dd8200fc-61b8-4d38-8c30-15b54428be42","tags":[]}];
